insert into public.assessments (id, slug, kind, title_ua, cefr, module_id, order_index, pass_ratio, area_min_ratio, estimated_minutes, description_ua, status, source)
values ('d8d47ac0-4c36-5d65-82b1-dc972598cece', 'a1-m01', 'module', 'Перевірка модуля A1.1', 'A1', (select id from public.modules where level_code = 'A1' and order_index = 1), 1, 0.70, 0.50, 5, 'Після модуля: 10 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~5 хв.', 'PUBLISHED', 'claude_assessment_v1')
