insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options, correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('de7a1073-1645-56d1-b1db-46d6984281e3', 'd8d47ac0-4c36-5d65-82b1-dc972598cece', 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Так рано! Чому?", "Можна в четвер увечері?", "Коли ти зазвичай прокидаєшся?"]'::jsonb, 1, null, 'Može u četvrtak navečer?', null, null, 'Прозвучало: «Može u četvrtak navečer?» — «Можна в четвер увечері?».', (select id from public.lessons where id = '3365f423-e694-5b55-baa1-3205fba11aff'), 'PUBLISHED', 'claude_assessment_v1'),
  ('fc910b05-b24a-53a9-b206-c1b49a204982', 'd8d47ac0-4c36-5d65-82b1-dc972598cece', 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Ні, сьогодні субота. Я ще трохи подрімаю.", "Він утомився. Спочатку його скупаємо, а потім перевдягни його.", "Мушу подивитися розклад. У мене багато справ."]'::jsonb, 0, null, 'Ne, danas je subota. Još malo drijemam.', null, null, 'Прозвучало: «Ne, danas je subota. Još malo drijemam.» — «Ні, сьогодні субота. Я ще трохи подрімаю.».', (select id from public.lessons where id = '63a4a6d8-1cae-5e0e-90ff-98efcfe8b4c7'), 'PUBLISHED', 'claude_assessment_v1'),
  ('fb2b13cf-d991-5a63-8ce8-61bfe89f36cf', 'd8d47ac0-4c36-5d65-82b1-dc972598cece', 3, 'A1', 'reading', 'understand', 'multiple_choice', 'Куди Ана йде в суботу?', 'Poruka od prijateljice', '["На роботу", "До лікаря", "На ринок і на каву"]'::jsonb, 2, null, null, 'Bok, Olena! Jesi li slobodna u subotu ujutro? Idem na tržnicu po voće i povrće, a onda na kavu. Hoćeš li sa mnom? Možemo se naći u devet ispred pekare. Javi mi! Ana', 'Привіт, Олено! Ти вільна в суботу вранці? Я йду на ринок по фрукти й овочі, а потім на каву. Підеш зі мною? Можемо зустрітися о дев’ятій перед пекарнею. Дай знати! Ана', 'Текст «Повідомлення від подруги». Правильна відповідь: «На ринок і на каву».', null, 'PUBLISHED', 'claude_assessment_v1'),
  ('7bd83af9-91e0-56bd-be46-adce17e51a1a', 'd8d47ac0-4c36-5d65-82b1-dc972598cece', 4, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Možemo li se naći ovaj tjedan?', '["Na festivalu u Puli, u Areni.", "Moram pogledati raspored. Imam puno obveza.", "Na trgu u centru. Slavlje traje do jutra!"]'::jsonb, 1, null, 'Možemo li se naći ovaj tjedan?', null, null, 'Діалог «Коли ти вільний?»: «Možemo li se naći ovaj tjedan?» (Можемо зустрітися цього тижня?) — «Moram pogledati raspored. Imam puno obveza.» (Мушу подивитися розклад. У мене багато справ.).', (select id from public.lessons where id = '3365f423-e694-5b55-baa1-3205fba11aff'), 'PUBLISHED', 'claude_assessment_v1'),
  ('6a6c433f-f4c8-5f7e-94e0-2619831498bd', 'd8d47ac0-4c36-5d65-82b1-dc972598cece', 5, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Opet? Što ja radim?', '["Trebamo madrac i komodu za spavaću sobu.", "S osiguranjem ne plaćate ništa.", "Ti usisavaš sobe, a tata pere suđe."]'::jsonb, 2, null, 'Opet? Što ja radim?', null, null, 'Діалог «Субота вдома»: «Opet? Što ja radim?» (Знову? А що роблю я?) — «Ti usisavaš sobe, a tata pere suđe.» (Ти пилососиш кімнати, а тато миє посуд.).', (select id from public.lessons where id = '9c38f909-9275-5194-9a6e-f799c6e416ce'), 'PUBLISHED', 'claude_assessment_v1'),
  ('b905e9f4-3c3e-58f4-a786-9489793f5267', 'd8d47ac0-4c36-5d65-82b1-dc972598cece', 6, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Kako provodiš vikend?', '["Відпочиваю. Готую і слухаю музику.", "Я теж люблю хорватську музику!", "Хорватську й українську."]'::jsonb, 0, null, null, 'Petra: Kako provodiš vikend?
Andrij: Odmaram se. Kuham i slušam glazbu.
Petra: Koju glazbu slušaš?
Andrij: Hrvatsku i ukrajinsku.
Petra: I ja volim hrvatsku glazbu!', 'Petra: Як ти проводиш вихідні?
Andrij: Відпочиваю. Готую і слухаю музику.
Petra: Яку музику ти слухаєш?
Andrij: Хорватську й українську.
Petra: Я теж люблю хорватську музику!', 'Діалог «Спокійні вихідні»: «Kako provodiš vikend?» — «Odmaram se. Kuham i slušam glazbu.», тобто «Відпочиваю. Готую і слухаю музику.».', (select id from public.lessons where id = '458b73de-d6b3-5bd3-98ad-c243a2fff03f'), 'PUBLISHED', 'claude_assessment_v1'),
  ('8a4d1332-adc0-54db-826b-06b6919458ce', 'd8d47ac0-4c36-5d65-82b1-dc972598cece', 7, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я хочу спланувати тиждень». Що ви скажете?', null, '["Dobar san je jako važan.", "Želim planirati tjedan.", "Koji je tvoj plan za vikend?"]'::jsonb, 1, null, null, null, null, '«Я хочу спланувати тиждень.» — «Želim planirati tjedan.».', (select id from public.lessons where id = '3365f423-e694-5b55-baa1-3205fba11aff'), 'PUBLISHED', 'claude_assessment_v1'),
  ('f6dba86a-ddfb-5dcd-8376-4e4958872374', 'd8d47ac0-4c36-5d65-82b1-dc972598cece', 8, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «надворі»', null, '[]'::jsonb, null, 'vani', null, null, null, '«надворі» — vani.', (select id from public.lessons where id = '54f17cf7-3c17-5978-b400-b6b6888c9f84'), 'PUBLISHED', 'claude_assessment_v1'),
  ('44af2974-8851-5e3a-97fc-97df9cfa128e', 'd8d47ac0-4c36-5d65-82b1-dc972598cece', 9, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Обідаю на роботі.»', null, '["na", "Ručam", "poslu."]'::jsonb, null, 'Ručam na poslu.', null, null, null, '«Обідаю на роботі.» — «Ručam na poslu.».', (select id from public.lessons where id = '4bf48151-be83-5108-bc92-645c0603a1a3'), 'PUBLISHED', 'claude_assessment_v1'),
  ('1399b653-849a-5820-a017-fb9675c783a9', 'd8d47ac0-4c36-5d65-82b1-dc972598cece', 10, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Я ніколи не п’ю каву.»', null, '[]'::jsonb, null, 'Nikad ne pijem kavu.', null, null, null, '«Я ніколи не п’ю каву.» — «Nikad ne pijem kavu.».', (select id from public.lessons where id = '959e879f-a28d-5bed-9c09-16cff91ef456'), 'PUBLISHED', 'claude_assessment_v1')
on conflict (id) do nothing;

