values ('1c2ae4dd-5513-5cfe-af37-8c86e92a93fb', 'a1-m02', 'module', 'Перевірка модуля A1.2', 'A1', (select id from public.modules where level_code = 'A1' and order_index = 2), 2, 0.70, 0.50, 5, 'Після модуля: 10 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~5 хв.', 'PUBLISHED', 'claude_assessment_v1')
