insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options, correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('7e78530c-d688-582a-87ee-f5499b60f88a', '1c2ae4dd-5513-5cfe-af37-8c86e92a93fb', 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Так, один йогурт. І каву з собою.", "Кілограм винограду й півкілограма груш, будь ласка.", "І ця страва дуже гостра."]'::jsonb, 1, null, 'Kilogram grožđa i pola kilograma krušaka, molim.', null, null, 'Прозвучало: «Kilogram grožđa i pola kilograma krušaka, molim.» — «Кілограм винограду й півкілограма груш, будь ласка.».', (select id from public.lessons where id = '46a89cf5-41e0-50a2-99b1-f4e66a5ff146'), 'PUBLISHED', 'claude_assessment_v1'),
  ('a76d528d-febc-5232-80e7-a32c744cec54', '1c2ae4dd-5513-5cfe-af37-8c86e92a93fb', 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Наріж цибулю й часник.", "Пюре або варена картопля. Візьміть тацю.", "І ця страва дуже гостра."]'::jsonb, 1, null, 'Pire ili kuhani krumpir. Uzmite pladanj.', null, null, 'Прозвучало: «Pire ili kuhani krumpir. Uzmite pladanj.» — «Пюре або варена картопля. Візьміть тацю.».', (select id from public.lessons where id = '2c192d05-f259-53b6-a6ec-55ebfb25ec01'), 'PUBLISHED', 'claude_assessment_v1'),
  ('496bd549-766f-594f-b58f-dce8095e0c35', '1c2ae4dd-5513-5cfe-af37-8c86e92a93fb', 3, 'A1', 'reading', 'understand', 'multiple_choice', 'Скільки коштує денне меню?', 'Dnevni meni', '["16 €", "9 €", "11 €"]'::jsonb, 1, null, null, 'DNEVNI MENI – 9 €
Juha od rajčice
Pečena piletina, krumpir i salata
ili
Varivo od graha s kobasicom
Kolač dana
Kruh i voda su besplatni. Kavu plaćate posebno.
Radimo od 11 do 16 sati.', 'ДЕННЕ МЕНЮ – 9 €
Томатний суп
Запечена курка, картопля й салат
або
Рагу з квасолі з ковбаскою
Тістечко дня
Хліб і вода безкоштовні. За каву платите окремо.
Працюємо з 11 до 16 години.', 'Текст «Денне меню». Правильна відповідь: «9 €».', null, 'PUBLISHED', 'claude_assessment_v1'),
  ('c7543ab2-e25d-51ae-8918-00c9c37cc521', '1c2ae4dd-5513-5cfe-af37-8c86e92a93fb', 4, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'S čokoladom. Imate li i neki slani namaz?', '["Rijetko, zbog hladnoće.", "Smijete, ali morate platiti. Ovo je druga zona.", "Imamo namaz od sira i salamu."]'::jsonb, 2, null, 'S čokoladom. Imate li i neki slani namaz?', null, null, 'Діалог «У пекарні»: «S čokoladom. Imate li i neki slani namaz?» (З шоколадом. А у вас є якась солона намазка?) — «Imamo namaz od sira i salamu.» (Є сирна намазка і салямі.).', (select id from public.lessons where id = 'bb7bc159-cb40-5a8a-91b7-c6da05c6342a'), 'PUBLISHED', 'claude_assessment_v1'),
  ('44396cff-28de-5810-9efd-bdf6067556c0', '1c2ae4dd-5513-5cfe-af37-8c86e92a93fb', 5, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Evo. Mogu li probati?', '["Možeš. Pazi, vruće je!", "Umoran je. Prvo ga kupamo, a onda ga presvuci.", "Nekoliko eura. Ovjeru dobivate odmah."]'::jsonb, 0, null, 'Evo. Mogu li probati?', null, null, 'Діалог «Накриваємо на стіл»: «Evo. Mogu li probati?» (Ось. Можна скуштувати?) — «Možeš. Pazi, vruće je!» (Можна. Обережно, гаряче!).', (select id from public.lessons where id = '3e652232-866b-5edf-ac05-d61ee7a325fe'), 'PUBLISHED', 'claude_assessment_v1'),
  ('6fe7afd7-380a-588d-9d66-3855e162516d', '1c2ae4dd-5513-5cfe-af37-8c86e92a93fb', 6, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Koliko košta kilogram srdela?', '["П’ять євро. Свіжі, з самого ранку.", "Можете їх почистити?", "Звісно. Хочете ще трохи кальмарів чи мідій?"]'::jsonb, 0, null, null, 'Taras: Koliko košta kilogram srdela?
Prodavač: Pet eura. Svježe su, od jutros.
Taras: Možete li ih očistiti?
Prodavač: Naravno. Želite li i malo lignji ili dagnji?
Taras: Ne, žena ne voli plodove mora. Ali uzimam file bez kostiju.', 'Taras: Скільки коштує кілограм сардин?
Prodavač: П’ять євро. Свіжі, з самого ранку.
Taras: Можете їх почистити?
Prodavač: Звісно. Хочете ще трохи кальмарів чи мідій?
Taras: Ні, дружина не любить морепродукти. Але візьму філе без кісток.', 'Діалог «На рибному ринку»: «Koliko košta kilogram srdela?» — «Pet eura. Svježe su, od jutros.», тобто «П’ять євро. Свіжі, з самого ранку.».', (select id from public.lessons where id = 'ae33e31a-f937-5305-908e-3d957df15f6a'), 'PUBLISHED', 'claude_assessment_v1'),
  ('19503c83-a7df-578c-bc7b-95f66a825bff', '1c2ae4dd-5513-5cfe-af37-8c86e92a93fb', 7, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Пляшку води, будь ласка». Що ви скажете?', null, '["Ne jedem slatko za doručak.", "Bocu vode, molim.", "Čaj bez šećera, molim."]'::jsonb, 1, null, null, null, null, '«Пляшку води, будь ласка.» — «Bocu vode, molim.».', (select id from public.lessons where id = '46a89cf5-41e0-50a2-99b1-f4e66a5ff146'), 'PUBLISHED', 'claude_assessment_v1'),
  ('eac42c0b-06fa-5f92-a144-13d8201b2a12', '1c2ae4dd-5513-5cfe-af37-8c86e92a93fb', 8, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «замовити»', null, '[]'::jsonb, null, 'naručiti', null, null, null, '«замовити» — naručiti.', (select id from public.lessons where id = '5e4a1c56-3931-58bb-81af-cb598966da77'), 'PUBLISHED', 'claude_assessment_v1'),
  ('99fe5e17-5d4b-520f-8e5b-ab25e6ed5936', '1c2ae4dd-5513-5cfe-af37-8c86e92a93fb', 9, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Цукор на столі.»', null, '["Šećer", "na", "je", "stolu."]'::jsonb, null, 'Šećer je na stolu.', null, null, null, '«Цукор на столі.» — «Šećer je na stolu.».', (select id from public.lessons where id = '1e8c2d0e-28f6-5873-aa9f-5d0ad2567fb8'), 'PUBLISHED', 'claude_assessment_v1'),
  ('932b9bdf-325c-5f0b-b207-798f4fee27fa', '1c2ae4dd-5513-5cfe-af37-8c86e92a93fb', 10, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Я не їм солодкого на сніданок.»', null, '[]'::jsonb, null, 'Ne jedem slatko za doručak.', null, null, null, '«Я не їм солодкого на сніданок.» — «Ne jedem slatko za doručak.».', (select id from public.lessons where id = 'bb7bc159-cb40-5a8a-91b7-c6da05c6342a'), 'PUBLISHED', 'claude_assessment_v1')
on conflict (id) do nothing;

