insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options, correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('1cea64b5-ae95-509d-a890-f09e5a882231', '59714d76-a9c1-53d1-9d9c-c0cee728d955', 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Звісно. Введіть PIN.", "Так, але вона краща для зими.", "У кінці, праворуч, біля дитячого крему."]'::jsonb, 1, null, 'Da, ali je bolja za zimu.', null, null, 'Прозвучало: «Da, ali je bolja za zimu.» — «Так, але вона краща для зими.».', (select id from public.lessons where id = '7042ff57-9a20-514a-ab80-71b6f63579f7'), 'PUBLISHED', 'claude_assessment_v1'),
  ('970e07f3-b7a4-5ee3-8f70-ebcca500e147', '59714d76-a9c1-53d1-9d9c-c0cee728d955', 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Добре, беру чорну.", "Можемо його обміняти або повернути гроші.", "Є, ось він."]'::jsonb, 2, null, 'Imam, evo ga.', null, null, 'Прозвучало: «Imam, evo ga.» — «Є, ось він.».', (select id from public.lessons where id = '6a7b0f42-510b-521e-9cc0-f77b2659d838'), 'PUBLISHED', 'claude_assessment_v1'),
  ('e878b60f-97d5-53fb-a5c7-b7094b571c83', '59714d76-a9c1-53d1-9d9c-c0cee728d955', 3, 'A1', 'reading', 'understand', 'multiple_choice', 'Що буде, якщо вас немає вдома?', 'SMS od kurira', '["Посилку повернуть", "Посилку залишать у поштоматі", "Кур’єр прийде завтра"]'::jsonb, 1, null, null, 'Poštovani, Vaša pošiljka stiže danas između 14 i 17 sati. Kurir Vas zove prije dostave. Ako niste kod kuće, paket ostavljamo u paketomatu na adresi Ilica 25. Kod za otvaranje dobivate u novoj poruci. Za praćenje pošiljke posjetite našu stranicu.', 'Шановний(-а), ваша посилка прибуде сьогодні між 14 і 17 годиною. Кур’єр подзвонить вам перед доставкою. Якщо вас немає вдома, посилку залишимо в поштоматі за адресою Іліца, 25. Код для відкриття отримаєте в новому повідомленні. Щоб відстежити посилку, відвідайте наш сайт.', 'Текст «SMS від кур’єра». Правильна відповідь: «Посилку залишать у поштоматі».', null, 'PUBLISHED', 'claude_assessment_v1'),
  ('205050c4-d079-52ab-9dad-8f5e0601eea2', '59714d76-a9c1-53d1-9d9c-c0cee728d955', 4, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'A rukavice? Gdje su mi rukavice?', '["U ladici, pored čarapa.", "Oko tri sata autom. Na zapadu je.", "Jako. I romantičan je, vodi me na večeru uz more."]'::jsonb, 0, null, 'A rukavice? Gdje su mi rukavice?', null, null, 'Діалог «Що вдягти?»: «A rukavice? Gdje su mi rukavice?» (А рукавички? Де мої рукавички?) — «U ladici, pored čarapa.» (У шухляді, біля шкарпеток.).', (select id from public.lessons where id = 'c8297811-44ed-55a2-8cb5-d1bd9b8a6a73'), 'PUBLISHED', 'claude_assessment_v1'),
  ('b1f84c82-f740-5b18-91c8-c59b9ae147ad', '59714d76-a9c1-53d1-9d9c-c0cee728d955', 5, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Da, jednu. Mogu li platiti karticom?', '["Tisuću dvjesto eura neto.", "Naravno. Unesite PIN.", "Rijetko, zbog hladnoće."]'::jsonb, 1, null, 'Da, jednu. Mogu li platiti karticom?', null, null, 'Діалог «На касі»: «Da, jednu. Mogu li platiti karticom?» (Так, один. Можна заплатити карткою?) — «Naravno. Unesite PIN.» (Звісно. Введіть PIN.).', (select id from public.lessons where id = '0c19643d-57ff-5030-820f-ba330833ea88'), 'PUBLISHED', 'claude_assessment_v1'),
  ('771a89f6-b11d-57f6-a0f8-9cb3400024f5', '59714d76-a9c1-53d1-9d9c-c0cee728d955', 6, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Trebate li pomoć?', '["Беру кращі. І одну бавовняну піжаму.", "Піжами ліворуч, біля спідниць.", "Шукаю непромокальні чоботи для доньки."]'::jsonb, 2, null, null, 'Prodavač: Trebate li pomoć?
Taras: Tražim nepromočive čizme za kćer.
Prodavač: Ove su najbolje. A ove su jeftinije, ali tanje.
Taras: Uzimam bolje. I jednu pidžamu od pamuka.
Prodavač: Pidžame su lijevo, kod suknji.', 'Prodavač: Вам допомогти?
Taras: Шукаю непромокальні чоботи для доньки.
Prodavač: Ці найкращі. А ці дешевші, але тонші.
Taras: Беру кращі. І одну бавовняну піжаму.
Prodavač: Піжами ліворуч, біля спідниць.', 'Діалог «Купуємо чоботи»: «Trebate li pomoć?» — «Tražim nepromočive čizme za kćer.», тобто «Шукаю непромокальні чоботи для доньки.».', (select id from public.lessons where id = 'c8297811-44ed-55a2-8cb5-d1bd9b8a6a73'), 'PUBLISHED', 'claude_assessment_v1'),
  ('cce4a643-e6a9-5246-8775-a41c1d30f7e2', '59714d76-a9c1-53d1-9d9c-c0cee728d955', 7, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Мені треба платити готівкою?». Що ви скажете?', null, '["Isključi mobitel, molim te.", "Ormar moramo sami sklopiti.", "Moram li platiti gotovinom?"]'::jsonb, 2, null, null, null, null, '«Мені треба платити готівкою?» — «Moram li platiti gotovinom?».', (select id from public.lessons where id = '0c19643d-57ff-5030-820f-ba330833ea88'), 'PUBLISHED', 'claude_assessment_v1'),
  ('20a44240-7d5f-5e7f-afe1-83cb5dbc65ce', '59714d76-a9c1-53d1-9d9c-c0cee728d955', 8, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «черга»', null, '[]'::jsonb, null, 'red', null, null, null, '«черга» — red.', (select id from public.lessons where id = '0c19643d-57ff-5030-820f-ba330833ea88'), 'PUBLISHED', 'claude_assessment_v1'),
  ('d62ebf52-4bd8-5ea6-baa3-cf5310843f13', '59714d76-a9c1-53d1-9d9c-c0cee728d955', 9, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Мій телефон не заряджається.»', null, '["ne", "se", "puni.", "mobitel", "Moj"]'::jsonb, null, 'Moj mobitel se ne puni.', null, null, null, '«Мій телефон не заряджається.» — «Moj mobitel se ne puni.».', (select id from public.lessons where id = '35203547-5f9a-5857-95a0-3a0d596f715d'), 'PUBLISHED', 'claude_assessment_v1'),
  ('f3401ef8-a50f-5987-ad01-86dcf5587f2c', '59714d76-a9c1-53d1-9d9c-c0cee728d955', 10, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Пульт лежить на столику.»', null, '[]'::jsonb, null, 'Daljinski je na stoliću.', null, null, null, '«Пульт лежить на столику.» — «Daljinski je na stoliću.».', (select id from public.lessons where id = 'de93d3ab-6769-5daf-9560-8858285a8136'), 'PUBLISHED', 'claude_assessment_v1')
on conflict (id) do nothing;

