insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options, correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('268ef067-bd61-573a-b9f7-7e31980730ab', '823e12bc-9d98-513a-81c8-9085db2d7e33', 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Можна, але треба заплатити. Це друга зона.", "Покладіть валізу в багажник.", "Негайно, будь ласка. Я їду на вокзал."]'::jsonb, 2, null, 'Odmah, molim. Idem na kolodvor.', null, null, 'Прозвучало: «Odmah, molim. Idem na kolodvor.» — «Негайно, будь ласка. Я їду на вокзал.».', (select id from public.lessons where id = '458ee6ec-31d1-5758-adef-03612626088a'), 'PUBLISHED', 'claude_assessment_v1'),
  ('de0fe50e-91bf-597e-a621-6b471c810a35', '823e12bc-9d98-513a-81c8-9085db2d7e33', 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Вашу валізу покладіть у багажне відділення.", "Зупиніться! Не можна їздити на самокаті по тротуару.", "Один квиток туди й назад, будь ласка."]'::jsonb, 1, null, 'Stanite! Ne smijete voziti romobil po pločniku.', null, null, 'Прозвучало: «Stanite! Ne smijete voziti romobil po pločniku.» — «Зупиніться! Не можна їздити на самокаті по тротуару.».', (select id from public.lessons where id = '0b04119b-4d38-5d99-8237-caa95fdcfd95'), 'PUBLISHED', 'claude_assessment_v1'),
  ('ab62d5d8-8083-51f5-9153-2d18eafd30f0', '823e12bc-9d98-513a-81c8-9085db2d7e33', 3, 'A1', 'reading', 'understand', 'multiple_choice', 'Чи потрібен новий квиток на автобус?', 'Promjena linije tramvaja', '["Так, у водія", "Так, треба купити", "Ні, квиток дійсний"]'::jsonb, 2, null, null, 'OBAVIJEST PUTNICIMA
Zbog radova na cesti tramvaj broj 6 od ponedjeljka ne vozi do Glavnog kolodvora.
Putnici mogu presjedati na autobus broj 109 na stanici Trg bana Jelačića.
Karta vrijedi za tramvaj i za autobus.
Hvala na razumijevanju!', 'ОГОЛОШЕННЯ ДЛЯ ПАСАЖИРІВ
Через дорожні роботи трамвай номер 6 з понеділка не їздить до Головного вокзалу.
Пасажири можуть пересісти на автобус номер 109 на зупинці «Площа бана Єлачича».
Квиток дійсний і для трамвая, і для автобуса.
Дякуємо за розуміння!', 'Текст «Зміна маршруту трамвая». Правильна відповідь: «Ні, квиток дійсний».', null, 'PUBLISHED', 'claude_assessment_v1'),
  ('d7af4cd3-d984-5679-9b20-7282cf18b44a', '823e12bc-9d98-513a-81c8-9085db2d7e33', 4, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Opet kolona! Ima li obilaznica?', '["Na Zlatnom ratu. More je predivno, kupamo se svaki dan!", "Ima. Na kružnom toku skreni u smjeru Zagreba.", "Obuci plave hlače i bijelu majicu."]'::jsonb, 1, null, 'Opet kolona! Ima li obilaznica?', null, null, 'Діалог «Затор»: «Opet kolona! Ima li obilaznica?» (Знову затор! Є об’їзна дорога?) — «Ima. Na kružnom toku skreni u smjeru Zagreba.» (Є. На кільці поверни в напрямку Загреба.).', (select id from public.lessons where id = '06f927cf-f38c-51b5-a1f9-696698ad23fb'), 'PUBLISHED', 'claude_assessment_v1'),
  ('d6c89f51-08b9-5cd7-aca7-02aa29a437a5', '823e12bc-9d98-513a-81c8-9085db2d7e33', 5, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Mogu. Koliko košta popravak?', '["Pržimo kupus s lukom u tavi.", "Ne znam još. Zovem Vas kad je gotov.", "Svaki je lijep na svoj način!"]'::jsonb, 1, null, 'Mogu. Koliko košta popravak?', null, null, 'Діалог «Дивний звук»: «Mogu. Koliko košta popravak?» (Можу. Скільки коштує ремонт?) — «Ne znam još. Zovem Vas kad je gotov.» (Ще не знаю. Подзвоню вам, коли буде готовий.).', (select id from public.lessons where id = 'cd5db261-a421-511d-8100-f86bf2335bbe'), 'PUBLISHED', 'claude_assessment_v1'),
  ('cc3c3819-34c6-5123-8750-44c195d4973e', '823e12bc-9d98-513a-81c8-9085db2d7e33', 6, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Oprostite, smijem li ovdje parkirati?', '["Можна, але треба заплатити. Це друга зона.", "Дякую! Не хочу штрафу.", "Он там. Або заплатіть через SMS."]'::jsonb, 0, null, null, 'Iryna: Oprostite, smijem li ovdje parkirati?
Prolaznik: Smijete, ali morate platiti. Ovo je druga zona.
Iryna: Gdje je automat?
Prolaznik: Tamo. Ili platite SMS-om.
Iryna: Hvala! Ne želim kaznu.', 'Iryna: Вибачте, мені можна тут паркуватися?
Prolaznik: Можна, але треба заплатити. Це друга зона.
Iryna: Де паркомат?
Prolaznik: Он там. Або заплатіть через SMS.
Iryna: Дякую! Не хочу штрафу.', 'Діалог «Де можна паркуватися?»: «Oprostite, smijem li ovdje parkirati?» — «Smijete, ali morate platiti. Ovo je druga zona.», тобто «Можна, але треба заплатити. Це друга зона.».', (select id from public.lessons where id = 'd6ca64d8-4c71-5936-a930-51e400f5681d'), 'PUBLISHED', 'claude_assessment_v1'),
  ('123b3b8a-e8f2-5f8f-a08d-4aa9f55b02a0', '823e12bc-9d98-513a-81c8-9085db2d7e33', 7, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Без шолома небезпечно». Що ви скажете?', null, '["S kojeg perona?", "Treba promijeniti filter.", "Bez kacige je opasno."]'::jsonb, 2, null, null, null, null, '«Без шолома небезпечно.» — «Bez kacige je opasno.».', (select id from public.lessons where id = '0b04119b-4d38-5d99-8237-caa95fdcfd95'), 'PUBLISHED', 'claude_assessment_v1'),
  ('83d087fc-dd66-5ad9-b3f4-375f701e5c01', '823e12bc-9d98-513a-81c8-9085db2d7e33', 8, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «об’їзна дорога»', null, '[]'::jsonb, null, 'obilaznica', null, null, null, '«об’їзна дорога» — obilaznica.', (select id from public.lessons where id = '06f927cf-f38c-51b5-a1f9-696698ad23fb'), 'PUBLISHED', 'claude_assessment_v1'),
  ('c39f44bd-ab0a-5106-bbb8-f78598e55f20', '823e12bc-9d98-513a-81c8-9085db2d7e33', 9, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Їдь обережно по велодоріжці.»', null, '["po", "biciklističkoj", "pažljivo", "Vozi", "stazi."]'::jsonb, null, 'Vozi pažljivo po biciklističkoj stazi.', null, null, null, '«Їдь обережно по велодоріжці.» — «Vozi pažljivo po biciklističkoj stazi.».', (select id from public.lessons where id = '0b04119b-4d38-5d99-8237-caa95fdcfd95'), 'PUBLISHED', 'claude_assessment_v1'),
  ('954401c6-32ac-5fe2-ab5d-774b113e9ce0', '823e12bc-9d98-513a-81c8-9085db2d7e33', 10, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Покладіть валізу в багажник.»', null, '[]'::jsonb, null, 'Stavite kofer u prtljažnik.', null, null, null, '«Покладіть валізу в багажник.» — «Stavite kofer u prtljažnik.».', (select id from public.lessons where id = '458ee6ec-31d1-5758-adef-03612626088a'), 'PUBLISHED', 'claude_assessment_v1')
on conflict (id) do nothing;

