values ('4984b13d-10d7-50a3-a7b6-6becf26caadb', 'a1-m05', 'module', 'Перевірка модуля A1.5', 'A1', (select id from public.modules where level_code = 'A1' and order_index = 5), 5, 0.70, 0.50, 5, 'Після модуля: 10 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~5 хв.', 'PUBLISHED', 'claude_assessment_v1')
