insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options, correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('77fe9cdf-a761-5360-ad7c-ae89e9bdc66c', '4984b13d-10d7-50a3-a7b6-6becf26caadb', 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Чи можна сушити білизну на балконі?", "Приємно познайомитися. Де наша поштова скринька?", "Скільки коштує оренда?"]'::jsonb, 0, null, 'Smijem li sušiti rublje na balkonu?', null, null, 'Прозвучало: «Smijem li sušiti rublje na balkonu?» — «Чи можна сушити білизну на балконі?».', (select id from public.lessons where id = 'f296bc84-8059-5981-a5b9-9d4531627e18'), 'PUBLISHED', 'claude_assessment_v1'),
  ('ebe7dd95-0bab-54cc-a1d1-4733f27da329', '4984b13d-10d7-50a3-a7b6-6becf26caadb', 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Вибачте! Занадто гучно?", "А кондиціонер? Він теж гріє?", "Мені теж. Куди ми викидаємо сміття?"]'::jsonb, 2, null, 'I meni. Gdje bacamo smeće?', null, null, 'Прозвучало: «I meni. Gdje bacamo smeće?» — «Мені теж. Куди ми викидаємо сміття?».', (select id from public.lessons where id = 'a42b9121-2ec0-5064-909b-f59f315b3c4a'), 'PUBLISHED', 'claude_assessment_v1'),
  ('51a94163-a4ce-5b26-a3c3-66d02235f4e2', '4984b13d-10d7-50a3-a7b6-6becf26caadb', 3, 'A1', 'reading', 'understand', 'multiple_choice', 'Куди викидати пляшку зі скла?', 'Odvajanje otpada', '["У жовтий", "У зелений контейнер", "У синій"]'::jsonb, 1, null, null, 'ODVAJAJTE OTPAD!
Plava kanta: papir i karton.
Žuta kanta: plastika i limenke.
Zelena kanta: staklo.
Smeđa kanta: ostaci hrane.
Crna kanta: ostalo smeće.
Smeće iznosimo navečer, prije osam sati. Velike stvari ne ostavljajte pored kanti.', 'СОРТУЙТЕ ВІДХОДИ!
Синій контейнер: папір і картон.
Жовтий контейнер: пластик і бляшанки.
Зелений контейнер: скло.
Коричневий контейнер: залишки їжі.
Чорний контейнер: інше сміття.
Сміття виносимо ввечері, до восьмої години. Великих речей не залишайте біля контейнерів.', 'Текст «Сміття й переробка». Правильна відповідь: «У зелений контейнер».', null, 'PUBLISHED', 'claude_assessment_v1'),
  ('dd88bc01-e2d2-5ea6-b617-1d60c44f2a6f', '4984b13d-10d7-50a3-a7b6-6becf26caadb', 4, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Mogu li se useliti prvog?', '["U kupaonici, pored sapuna. Brzo!", "Na sljedećoj. Onda uzmite šesticu.", "Možete. Ugovor potpisujemo sutra."]'::jsonb, 2, null, 'Mogu li se useliti prvog?', null, null, 'Діалог «Огляд квартири»: «Mogu li se useliti prvog?» (Чи можу я в’їхати першого числа?) — «Možete. Ugovor potpisujemo sutra.» (Можете. Договір підписуємо завтра.).', (select id from public.lessons where id = '278947e3-ae50-5818-abd7-7f07b8ab5c44'), 'PUBLISHED', 'claude_assessment_v1'),
  ('c0abd3a3-67e6-5060-8ded-4e2be5ec76ad', '4984b13d-10d7-50a3-a7b6-6becf26caadb', 5, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Nema problema. Imate li još pločica?', '["Imam. I promijenite, molim Vas, žarulju na stropu.", "U osam, kod mene.", "Igram, svake nedjelje s kolegama."]'::jsonb, 0, null, 'Nema problema. Imate li još pločica?', null, null, 'Діалог «Кран капає»: «Nema problema. Imate li još pločica?» (Без проблем. У вас є ще плитки?) — «Imam. I promijenite, molim Vas, žarulju na stropu.» (Є. І поміняйте, будь ласка, лампочку на стелі.).', (select id from public.lessons where id = 'dd2c0f3c-19f2-5c73-b448-a0631cd97e69'), 'PUBLISHED', 'claude_assessment_v1'),
  ('4eda1893-c544-5e2c-a618-7d4a405b2e67', '4984b13d-10d7-50a3-a7b6-6becf26caadb', 6, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Dobar dan! Vi ste novi susjed?', '["Так, я Тарас. Живу на другому поверсі.", "Унизу, біля парковки. Синій бак — для паперу.", "Я Ана, з п’ятої квартири. Приємно познайомитися!"]'::jsonb, 0, null, null, 'Susjeda: Dobar dan! Vi ste novi susjed?
Taras: Da, ja sam Taras. Živim na drugom katu.
Susjeda: Ja sam Ana, iz stana pet. Drago mi je!
Taras: I meni. Gdje bacamo smeće?
Susjeda: Dolje, pored parkirališta. Plava kanta je za papir.', 'Susjeda: Добрий день! Ви новий сусід?
Taras: Так, я Тарас. Живу на другому поверсі.
Susjeda: Я Ана, з п’ятої квартири. Приємно познайомитися!
Taras: Мені теж. Куди ми викидаємо сміття?
Susjeda: Унизу, біля парковки. Синій бак — для паперу.', 'Діалог «Знайомство на сходах»: «Dobar dan! Vi ste novi susjed?» — «Da, ja sam Taras. Živim na drugom katu.», тобто «Так, я Тарас. Живу на другому поверсі.».', (select id from public.lessons where id = 'a42b9121-2ec0-5064-909b-f59f315b3c4a'), 'PUBLISHED', 'claude_assessment_v1'),
  ('fdad5c55-a0d7-59ac-87d5-4f8d137d0a40', '4984b13d-10d7-50a3-a7b6-6becf26caadb', 7, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Тут заборонено курити». Що ви скажете?', null, '["Kada je selidba?", "Slavina u kuhinji kaplje.", "Ovdje je zabranjeno pušiti."]'::jsonb, 2, null, null, null, null, '«Тут заборонено курити.» — «Ovdje je zabranjeno pušiti.».', (select id from public.lessons where id = 'f296bc84-8059-5981-a5b9-9d4531627e18'), 'PUBLISHED', 'claude_assessment_v1'),
  ('c9e9ca00-342c-5f51-96a5-7edbc0b2b5cb', '4984b13d-10d7-50a3-a7b6-6becf26caadb', 8, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «капати»', null, '[]'::jsonb, null, 'kapati', null, null, null, '«капати» — kapati.', (select id from public.lessons where id = 'dd2c0f3c-19f2-5c73-b448-a0631cd97e69'), 'PUBLISHED', 'claude_assessment_v1'),
  ('02f0e366-4a88-5bef-a399-34cef31dac31', '4984b13d-10d7-50a3-a7b6-6becf26caadb', 9, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Мені подобається, бо вона світла.»', null, '["je", "Sviđa", "mi", "svijetao.", "jer", "se"]'::jsonb, null, 'Sviđa mi se jer je svijetao.', null, null, null, '«Мені подобається, бо вона світла.» — «Sviđa mi se jer je svijetao.».', (select id from public.lessons where id = '278947e3-ae50-5818-abd7-7f07b8ab5c44'), 'PUBLISHED', 'claude_assessment_v1'),
  ('7e6f7917-bc75-5e85-81e9-8b1692b9b1f6', '4984b13d-10d7-50a3-a7b6-6becf26caadb', 10, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Я вдома після п’ятої.»', null, '[]'::jsonb, null, 'Doma sam poslije pet.', null, null, null, '«Я вдома після п’ятої.» — «Doma sam poslije pet.».', (select id from public.lessons where id = '8fc3399d-0405-5517-9358-d3ad6308d860'), 'PUBLISHED', 'claude_assessment_v1')
on conflict (id) do nothing;

-- Перевірка середини рівня A1
insert into public.assessments (id, slug, kind, title_ua, cefr, module_id, order_index, pass_ratio, area_min_ratio, estimated_minutes, description_ua, status, source)
values ('982ea46f-9496-5310-8e5e-801bd386863b', 'a1-mid', 'mid', 'Перевірка середини рівня A1', 'A1', null, 50, 0.70, 0.50, 10, 'Середина рівня (модулі 1–5): 20 завдань на 4 навички. ~10 хв.', 'PUBLISHED', 'claude_assessment_v1')
