insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options, correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('e77aef9d-e78b-5994-a30c-fd73a7a553f4', '982ea46f-9496-5310-8e5e-801bd386863b', 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Ні, ми вечеряємо о сьомій.", "Нічого страшного. Пограйся ще п’ять хвилин.", "Добре. Дивись, він уже сміється!"]'::jsonb, 2, null, 'Dobro. Gle, već se smije!', null, null, 'Прозвучало: «Dobro. Gle, već se smije!» — «Добре. Дивись, він уже сміється!».', (select id from public.lessons where id = 'd43d6c65-1ce3-5c72-9ecd-cce2ed200fc2'), 'PUBLISHED', 'claude_assessment_v1'),
  ('fa0b6a8f-64a3-5357-a650-b04dbb513bfd', '982ea46f-9496-5310-8e5e-801bd386863b', 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Так, у суботу. За десять євро ми його й зберемо.", "Чудово, їх і поміряю.", "Ці найкращі. А ці дешевші, але тонші."]'::jsonb, 2, null, 'Ove su najbolje. A ove su jeftinije, ali tanje.', null, null, 'Прозвучало: «Ove su najbolje. A ove su jeftinije, ali tanje.» — «Ці найкращі. А ці дешевші, але тонші.».', (select id from public.lessons where id = 'c8297811-44ed-55a2-8cb5-d1bd9b8a6a73'), 'PUBLISHED', 'claude_assessment_v1'),
  ('131452ff-a2d9-5294-a20d-47c85d806f3a', '982ea46f-9496-5310-8e5e-801bd386863b', 3, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Мені потрібно пів кілограма фаршу.", "Ммм, чудово пахне!", "Чотири. І виделки, ножі й ложки."]'::jsonb, 1, null, 'Mmm, miriše odlično!', null, null, 'Прозвучало: «Mmm, miriše odlično!» — «Ммм, чудово пахне!».', (select id from public.lessons where id = '3e652232-866b-5edf-ac05-d61ee7a325fe'), 'PUBLISHED', 'claude_assessment_v1'),
  ('145ddc7b-7d56-5f2b-949c-a5eaa13a421e', '982ea46f-9496-5310-8e5e-801bd386863b', 4, 'A1', 'reading', 'understand', 'multiple_choice', 'Де краще купувати квитки?', 'Ljetni red plovidbe', '["На поромі", "В інтернеті", "У водія"]'::jsonb, 1, null, null, 'Od lipnja do rujna trajekti iz Splita za Brač voze svaki sat, od pet ujutro do ponoći. Ljeti je velika gužva, zato putnici trebaju kupiti karte na internetu. Auti moraju biti u luci pola sata prije polaska. Pješaci mogu doći petnaest minuta prije.', 'З червня до вересня пороми зі Спліта на Брач ходять щогодини, з п’ятої ранку до опівночі. Улітку велика черга, тому пасажирам треба купувати квитки в інтернеті. Автомобілі мають бути в порту за пів години до відправлення. Пішоходи можуть прийти за п’ятнадцять хвилин до відправлення.', 'Текст «Літній розклад поромів». Правильна відповідь: «В інтернеті».', null, 'PUBLISHED', 'claude_assessment_v1'),
  ('7dfa8a7b-4788-5fe3-955d-7e1e65b6aea7', '982ea46f-9496-5310-8e5e-801bd386863b', 5, 'A1', 'reading', 'understand', 'multiple_choice', 'Яка куртка дешевша?', 'Koju jaknu kupiti?', '["Синя", "Чорна", "Обидві однакові"]'::jsonb, 0, null, null, 'Oksana: Trebam zimsku jaknu za sina. Imaš li ideju?
Marija: Probaj u centru, tamo je sada sniženje.
Oksana: Vidim dvije jakne. Plava je jeftinija, a crna je toplija.
Marija: Uzmi topliju! Zima u Zagrebu je hladna.
Oksana: Imaš pravo. Uzimam crnu i nove rukavice.', 'Оксана: Мені потрібна зимова куртка для сина. Маєш ідею?
Марія: Спробуй у центрі, там зараз розпродаж.
Оксана: Бачу дві куртки. Синя дешевша, а чорна тепліша.
Марія: Бери теплішу! Зима в Загребі холодна.
Оксана: Маєш рацію. Беру чорну і нові рукавички.', 'Текст «Яку куртку купити?». Правильна відповідь: «Синя».', null, 'PUBLISHED', 'claude_assessment_v1'),
  ('7c688c27-a7c1-537c-a816-46bf4e4b3f9f', '982ea46f-9496-5310-8e5e-801bd386863b', 6, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Koliko traje vožnja?', '["Oko četiri sata.", "Uključuje se, ali nema zvuka. Ni kabel ne pomaže.", "Kajganu i tost, molim."]'::jsonb, 0, null, 'Koliko traje vožnja?', null, null, 'Діалог «На вокзалі»: «Koliko traje vožnja?» (Скільки триває поїздка?) — «Oko četiri sata.» (Близько чотирьох годин.).', (select id from public.lessons where id = 'cae7a47d-7fb4-5b03-a8cc-5a0df2ccd92f'), 'PUBLISHED', 'claude_assessment_v1'),
  ('fb5e9a27-146f-56bc-aefc-5f89dc98080f', '982ea46f-9496-5310-8e5e-801bd386863b', 7, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Koliko je najamnina?', '["Smijete, ali morate platiti. Ovo je druga zona.", "Rodni list, potvrda o cijepljenju i Vaš OIB.", "Petsto pedeset eura i režije."]'::jsonb, 2, null, 'Koliko je najamnina?', null, null, 'Діалог «Дзвінок щодо оголошення»: «Koliko je najamnina?» (Скільки коштує оренда?) — «Petsto pedeset eura i režije.» (П’ятсот п’ятдесят євро плюс комунальні.).', (select id from public.lessons where id = '278947e3-ae50-5818-abd7-7f07b8ab5c44'), 'PUBLISHED', 'claude_assessment_v1'),
  ('e7efe7eb-6b3a-568c-80f5-12f21753746a', '982ea46f-9496-5310-8e5e-801bd386863b', 8, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Izvolite, što tražite?', '["Oko četiristo. Autocestom treba četiri sata.", "Dragi putnici, vežite pojas. Krećemo!", "Trebamo madrac i komodu za spavaću sobu."]'::jsonb, 2, null, 'Izvolite, što tražite?', null, null, 'Діалог «У меблевому магазині»: «Izvolite, što tražite?» (Прошу, що шукаєте?) — «Trebamo madrac i komodu za spavaću sobu.» (Нам потрібні матрац і комод для спальні.).', (select id from public.lessons where id = 'de93d3ab-6769-5daf-9560-8858285a8136'), 'PUBLISHED', 'claude_assessment_v1'),
  ('174623b4-284a-53ca-8b2f-e3b8126ec255', '982ea46f-9496-5310-8e5e-801bd386863b', 9, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Što danas kuhamo?', '["Uzmite jednu tabletu tri puta dnevno.", "Pržimo kupus s lukom u tavi.", "Treba. Donesite diplomu i prijevod."]'::jsonb, 1, null, 'Što danas kuhamo?', null, null, 'Діалог «Вечеря на сковороді»: «Što danas kuhamo?» (Що сьогодні готуємо?) — «Pržimo kupus s lukom u tavi.» (Смажимо капусту з цибулею на сковороді.).', (select id from public.lessons where id = '17fcd38a-e295-5849-9ba3-1ef240c6be78'), 'PUBLISHED', 'claude_assessment_v1'),
  ('6f6f4b3b-a631-5631-b6a8-d7fc72b55e8d', '982ea46f-9496-5310-8e5e-801bd386863b', 10, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Mali plače. Što mu je?', '["Umoran je. Prvo ga kupamo, a onda ga presvuci.", "Dva eura. Karticu dobivate za deset dana.", "U deset. Ili noćni autobus u jedanaest navečer."]'::jsonb, 0, null, 'Mali plače. Što mu je?', null, null, 'Діалог «Вечір удома»: «Mali plače. Što mu je?» (Малий плаче. Що з ним?) — «Umoran je. Prvo ga kupamo, a onda ga presvuci.» (Він утомився. Спочатку його скупаємо, а потім перевдягни його.).', (select id from public.lessons where id = 'd43d6c65-1ce3-5c72-9ecd-cce2ed200fc2'), 'PUBLISHED', 'claude_assessment_v1'),
  ('50d874ef-ce9f-59c1-a995-76ac3cf94b6b', '982ea46f-9496-5310-8e5e-801bd386863b', 11, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Hvala. Plaćamo li pričuvu upravitelju zgrade?', '["Ви нові? Я Весна з другого поверху.", "Внизу біля входу. А велосипед не залишайте в коридорі, а в підвалі.", "Ні, платите за квитанцією. Тут усі дотримуються правил."]'::jsonb, 2, null, null, 'Susjeda: Vi ste novi? Ja sam Vesna s drugog kata.
Taras: Drago mi je. Gdje je naš poštanski sandučić?
Susjeda: Dolje kod ulaza. A bicikl ne ostavljajte u hodniku, nego u podrumu.
Taras: Hvala. Plaćamo li pričuvu upravitelju zgrade?
Susjeda: Ne, plaćate je uplatnicom. Svi ovdje poštuju pravila.', 'Susjeda: Ви нові? Я Весна з другого поверху.
Taras: Приємно познайомитися. Де наша поштова скринька?
Susjeda: Внизу біля входу. А велосипед не залишайте в коридорі, а в підвалі.
Taras: Дякую. Внесок на будинок платимо управителю?
Susjeda: Ні, платите за квитанцією. Тут усі дотримуються правил.', 'Діалог «Сусідка»: «Hvala. Plaćamo li pričuvu upravitelju zgrade?» — «Ne, plaćate je uplatnicom. Svi ovdje poštuju pravila.», тобто «Ні, платите за квитанцією. Тут усі дотримуються правил.».', (select id from public.lessons where id = 'f296bc84-8059-5981-a5b9-9d4531627e18'), 'PUBLISHED', 'claude_assessment_v1'),
  ('a232b777-065e-5a2e-920a-4e775146abbe', '982ea46f-9496-5310-8e5e-801bd386863b', 12, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Stalno liže šapu. Je li to problem?', '["Подивимося. Ні, з лапою все гаразд.", "Це Макс, наше цуценя. Йому три місяці.", "Сьогодні ми його щепимо. Потримайте його, будь ласка."]'::jsonb, 0, null, null, 'Veterinarka: Dobar dan. Koga imamo danas?
Andrij: Ovo je Max, naše štene. Ima tri mjeseca.
Veterinarka: Danas ga cijepimo. Držite ga, molim.
Andrij: Stalno liže šapu. Je li to problem?
Veterinarka: Da vidimo. Ne, šapa je u redu.', 'Veterinarka: Добрий день. Кого ми маємо сьогодні?
Andrij: Це Макс, наше цуценя. Йому три місяці.
Veterinarka: Сьогодні ми його щепимо. Потримайте його, будь ласка.
Andrij: Він постійно лиже лапу. Це проблема?
Veterinarka: Подивимося. Ні, з лапою все гаразд.', 'Діалог «У ветеринара»: «Stalno liže šapu. Je li to problem?» — «Da vidimo. Ne, šapa je u redu.», тобто «Подивимося. Ні, з лапою все гаразд.».', (select id from public.lessons where id = '1968c7d5-4e3a-5b1e-92f6-88df711e9c54'), 'PUBLISHED', 'claude_assessment_v1'),
  ('9c267b37-dcab-57ad-ae4c-863ddf96b129', '982ea46f-9496-5310-8e5e-801bd386863b', 13, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Soba je mala. Uzimamo usku. Možete li je dostaviti?', '["Так, у суботу. За десять євро ми його й зберемо.", "Яка у вас кімната? Цей комод широкий, а той вузький.", "Нам потрібні матрац і комод для спальні."]'::jsonb, 0, null, null, 'Prodavačica: Izvolite, što tražite?
Oksana: Trebamo madrac i komodu za spavaću sobu.
Prodavačica: Kolika je soba? Ova komoda je široka, a ona je uska.
Oksana: Soba je mala. Uzimamo usku. Možete li je dostaviti?
Prodavačica: Da, u subotu. Za deset eura je i montiramo.', 'Prodavačica: Прошу, що шукаєте?
Oksana: Нам потрібні матрац і комод для спальні.
Prodavačica: Яка у вас кімната? Цей комод широкий, а той вузький.
Oksana: Кімната маленька. Беремо вузький. Можете його доставити?
Prodavačica: Так, у суботу. За десять євро ми його й зберемо.', 'Діалог «У меблевому магазині»: «Soba je mala. Uzimamo usku. Možete li je dostaviti?» — «Da, u subotu. Za deset eura je i montiramo.», тобто «Так, у суботу. За десять євро ми його й зберемо.».', (select id from public.lessons where id = 'de93d3ab-6769-5daf-9560-8858285a8136'), 'PUBLISHED', 'claude_assessment_v1'),
  ('ca7f2911-5b07-5486-baf2-f208002c31f0', '982ea46f-9496-5310-8e5e-801bd386863b', 14, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Це мій паспорт». Що ви скажете?', null, '["Koliko plaćam?", "Ovo je moja putovnica.", "Mehaničar popravlja motor."]'::jsonb, 1, null, null, null, null, '«Це мій паспорт.» — «Ovo je moja putovnica.».', (select id from public.lessons where id = '69ec0776-4f69-5f86-afac-6652234a7da5'), 'PUBLISHED', 'claude_assessment_v1'),
  ('2cbece37-17e2-56f8-8715-ca2721ae7719', '982ea46f-9496-5310-8e5e-801bd386863b', 15, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Скільки коштує інтернет?». Що ви скажете?', null, '["Koliko košta internet?", "Kupac nije zadovoljan.", "Isključi mobitel, molim te."]'::jsonb, 0, null, null, null, null, '«Скільки коштує інтернет?» — «Koliko košta internet?».', (select id from public.lessons where id = '35203547-5f9a-5857-95a0-3a0d596f715d'), 'PUBLISHED', 'claude_assessment_v1'),
  ('429100c2-9cdf-54cb-a99a-0492bb171747', '982ea46f-9496-5310-8e5e-801bd386863b', 16, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «зона»', null, '[]'::jsonb, null, 'zona', null, null, null, '«зона» — zona.', (select id from public.lessons where id = 'd6ca64d8-4c71-5936-a930-51e400f5681d'), 'PUBLISHED', 'claude_assessment_v1'),
  ('a29a5860-20c8-56ed-a443-6db01d9f7acf', '982ea46f-9496-5310-8e5e-801bd386863b', 17, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «вакцинувати»', null, '[]'::jsonb, null, 'cijepiti', null, null, null, '«вакцинувати» — cijepiti.', (select id from public.lessons where id = '1968c7d5-4e3a-5b1e-92f6-88df711e9c54'), 'PUBLISHED', 'claude_assessment_v1'),
  ('f1e98bdb-ae69-537a-b029-23013dff0c6d', '982ea46f-9496-5310-8e5e-801bd386863b', 18, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Візьми наступний виїзд.»', null, '["izlaz.", "Uzmi", "sljedeći"]'::jsonb, null, 'Uzmi sljedeći izlaz.', null, null, null, '«Візьми наступний виїзд.» — «Uzmi sljedeći izlaz.».', (select id from public.lessons where id = '06f927cf-f38c-51b5-a1f9-696698ad23fb'), 'PUBLISHED', 'claude_assessment_v1'),
  ('b065af4e-6283-5f67-81c8-f5ca089d8b5f', '982ea46f-9496-5310-8e5e-801bd386863b', 19, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Почитай йому казку.»', null, '["Čitaj", "bajku.", "mu"]'::jsonb, null, 'Čitaj mu bajku.', null, null, null, '«Почитай йому казку.» — «Čitaj mu bajku.».', (select id from public.lessons where id = 'd43d6c65-1ce3-5c72-9ecd-cce2ed200fc2'), 'PUBLISHED', 'claude_assessment_v1'),
  ('2495ef20-94b8-5e0a-a165-110eacea6851', '982ea46f-9496-5310-8e5e-801bd386863b', 20, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Коли відправлення нічного автобуса?»', null, '[]'::jsonb, null, 'Kada je polazak noćnog autobusa?', null, null, null, '«Коли відправлення нічного автобуса?» — «Kada je polazak noćnog autobusa?».', (select id from public.lessons where id = 'c1b32b15-8f3c-5f75-bba9-e831d544ec7b'), 'PUBLISHED', 'claude_assessment_v1')
