-- Перевірка модуля A1.6 · Модуль A1.6 — Робота
insert into public.assessments (id, slug, kind, title_ua, cefr, module_id, order_index, pass_ratio, area_min_ratio, estimated_minutes, description_ua, status, source)
values ('50b88b49-abb3-59df-9aa8-f6c60655de84', 'a1-m06', 'module', 'Перевірка модуля A1.6', 'A1', (select id from public.modules where level_code = 'A1' and order_index = 6), 6, 0.70, 0.50, 5, 'Після модуля: 10 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~5 хв.', 'PUBLISHED', 'claude_assessment_v1')
