insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options, correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('bcbd9004-1a88-552c-8004-3c556d15e523', '50b88b49-abb3-59df-9aa8-f6c60655de84', 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Дякую! Можеш мені ще відсканувати цей паспорт?", "Де ти працюєш, у якому відділі?", "У вас є посвідчення на вантажівку?"]'::jsonb, 0, null, 'Hvala! Možeš li mi skenirati i ovu putovnicu?', null, null, 'Прозвучало: «Hvala! Možeš li mi skenirati i ovu putovnicu?» — «Дякую! Можеш мені ще відсканувати цей паспорт?».', (select id from public.lessons where id = 'ee016ba8-5160-581d-b440-1bcb7647173d'), 'PUBLISHED', 'claude_assessment_v1'),
  ('8b63471f-340a-5e9a-9d84-b10b11b9a3d6', '50b88b49-abb3-59df-9aa8-f6c60655de84', 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Не можна. Треба вийти надвір.", "Магазин шукає касирку й комірника.", "Сезонна, до жовтня. Надішліть мені резюме."]'::jsonb, 0, null, 'Ne smiješ. Moraš izaći van.', null, null, 'Прозвучало: «Ne smiješ. Moraš izaći van.» — «Не можна. Треба вийти надвір.».', (select id from public.lessons where id = '99088d92-0f0c-52c2-b51f-548d903fc9ef'), 'PUBLISHED', 'claude_assessment_v1'),
  ('b3d68ea2-34ba-5cb6-9d9e-c5c824e046b1', '50b88b49-abb3-59df-9aa8-f6c60655de84', 3, 'A1', 'reading', 'understand', 'multiple_choice', 'Що Оксана вчить від пані Марії?', 'Oksana na poslu', '["Водити машину", "Готувати", "Нові слова"]'::jsonb, 2, null, null, 'Oksana radi kao njegovateljica. Svako jutro dolazi kod gospođe Marije. Gospođa Marija ima osamdeset godina i živi sama. Oksana joj kuha ručak, ide s njom u šetnju i daje joj lijekove. Gospođa Marija joj priča o Zagrebu, a Oksana uči nove riječi. Posao nije lak, ali Oksana ga voli.', 'Оксана працює доглядальницею. Щоранку вона приходить до пані Марії. Пані Марії вісімдесят років, і вона живе сама. Оксана готує їй обід, ходить з нею на прогулянку й дає їй ліки. Пані Марія розповідає їй про Загреб, а Оксана вивчає нові слова. Робота не легка, але Оксана її любить.', 'Текст «Оксана на роботі». Правильна відповідь: «Нові слова».', null, 'PUBLISHED', 'claude_assessment_v1'),
  ('c8edf6b6-e9ec-598b-912c-7d34a9c094f2', '50b88b49-abb3-59df-9aa8-f6c60655de84', 4, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Hvala! Možeš li mi skenirati i ovu putovnicu?', '["Mogu. Datoteku spremam u mapu Klijenti.", "Pedeset minuta. Čekajte u drugom redu.", "Pakiranje je oštećeno, a šalica unutra je razbijena."]'::jsonb, 0, null, 'Hvala! Možeš li mi skenirati i ovu putovnicu?', null, null, 'Діалог «Принтер не друкує»: «Hvala! Možeš li mi skenirati i ovu putovnicu?» (Дякую! Можеш мені ще відсканувати цей паспорт?) — «Mogu. Datoteku spremam u mapu Klijenti.» (Можу. Файл зберігаю в папку «Клієнти».).', (select id from public.lessons where id = 'ee016ba8-5160-581d-b440-1bcb7647173d'), 'PUBLISHED', 'claude_assessment_v1'),
  ('c2f2a224-bffd-5f6f-a000-88773df720cb', '50b88b49-abb3-59df-9aa8-f6c60655de84', 5, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Znam. Trebam li donijeti potvrdu?', '["Odlična! Glumac u glavnoj ulozi je fantastičan.", "Da, za bolovanje. Ozdravite brzo!", "U deset. Ili noćni autobus u jedanaest navečer."]'::jsonb, 1, null, 'Znam. Trebam li donijeti potvrdu?', null, null, 'Діалог «Лікарняний»: «Znam. Trebam li donijeti potvrdu?» (Знаю. Мені треба принести довідку?) — «Da, za bolovanje. Ozdravite brzo!» (Так, для лікарняного. Одужуйте швидше!).', (select id from public.lessons where id = '99088d92-0f0c-52c2-b51f-548d903fc9ef'), 'PUBLISHED', 'claude_assessment_v1'),
  ('a221553b-305b-51ae-a137-2240b21c0fe3', '50b88b49-abb3-59df-9aa8-f6c60655de84', 6, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Imam dvije godine iskustva. Kakvi su uvjeti?', '["Добрий день, дзвоню щодо оголошення. Посада ще вільна?", "Погодинна оплата — вісім євро. Житло й харчування безкоштовні.", "Робота сезонна чи постійна?"]'::jsonb, 1, null, null, 'Andrij: Dobar dan, zovem zbog oglasa. Je li radno mjesto još slobodno?
Poslodavac: Jest. Tražimo konobara za sezonu. Imate li iskustva?
Andrij: Imam dvije godine iskustva. Kakvi su uvjeti?
Poslodavac: Satnica je osam eura. Smještaj i hrana su besplatni.
Andrij: Je li posao sezonski ili stalan?
Poslodavac: Sezonski, do listopada. Pošaljite mi životopis.', 'Andrij: Добрий день, дзвоню щодо оголошення. Посада ще вільна?
Poslodavac: Так. Шукаємо офіціанта на сезон. У вас є досвід?
Andrij: Маю два роки досвіду. Які умови?
Poslodavac: Погодинна оплата — вісім євро. Житло й харчування безкоштовні.
Andrij: Робота сезонна чи постійна?
Poslodavac: Сезонна, до жовтня. Надішліть мені резюме.', 'Діалог «Оголошення»: «Imam dvije godine iskustva. Kakvi su uvjeti?» — «Satnica je osam eura. Smještaj i hrana su besplatni.», тобто «Погодинна оплата — вісім євро. Житло й харчування безкоштовні.».', (select id from public.lessons where id = 'c9b87882-5e31-5485-aea7-0169216466a8'), 'PUBLISHED', 'claude_assessment_v1'),
  ('4baa908b-f0a3-5278-b792-4bdd5b2fb720', '50b88b49-abb3-59df-9aa8-f6c60655de84', 7, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Моя подруга — перукарка». Що ви скажете?', null, '["Kada je isplata?", "Moja prijateljica je frizerka.", "Mogu li razgovarati s gospodinom Babićem?"]'::jsonb, 1, null, null, null, null, '«Моя подруга — перукарка.» — «Moja prijateljica je frizerka.».', (select id from public.lessons where id = 'b369f01f-4a84-57b4-98cb-150d236f4d7f'), 'PUBLISHED', 'claude_assessment_v1'),
  ('b080fcff-ef6b-5b99-9972-818194e9ec41', '50b88b49-abb3-59df-9aa8-f6c60655de84', 8, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «залишити»', null, '[]'::jsonb, null, 'ostaviti', null, null, null, '«залишити» — ostaviti.', (select id from public.lessons where id = 'e806dd39-4d38-5781-ad2d-949961dd95f9'), 'PUBLISHED', 'claude_assessment_v1'),
  ('3e716c6c-8acf-56cc-a963-2533bf6b89ce', '50b88b49-abb3-59df-9aa8-f6c60655de84', 9, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Надішліть мені резюме.»', null, '["životopis.", "Pošaljite", "mi"]'::jsonb, null, 'Pošaljite mi životopis.', null, null, null, '«Надішліть мені резюме.» — «Pošaljite mi životopis.».', (select id from public.lessons where id = 'c9b87882-5e31-5485-aea7-0169216466a8'), 'PUBLISHED', 'claude_assessment_v1'),
  ('30ff7ef7-ea02-5db1-b85d-a6756fd15416', '50b88b49-abb3-59df-9aa8-f6c60655de84', 10, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Я працюю в офісі.»', null, '[]'::jsonb, null, 'Radim u uredu.', null, null, null, '«Я працюю в офісі.» — «Radim u uredu.».', (select id from public.lessons where id = 'd813e9c0-2331-59d8-90f1-cea7e9a61c7d'), 'PUBLISHED', 'claude_assessment_v1')
on conflict (id) do nothing;

