values ('f5d5e3db-f84c-57b2-b162-74f0a73dc299', 'a1-m07', 'module', 'Перевірка модуля A1.7', 'A1', (select id from public.modules where level_code = 'A1' and order_index = 7), 7, 0.70, 0.50, 5, 'Після модуля: 10 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~5 хв.', 'PUBLISHED', 'claude_assessment_v1')
