insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options, correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('2c5d054b-d9db-5451-908a-79c543d921bf', 'f5d5e3db-f84c-57b2-b162-74f0a73dc299', 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Зараз виміряю вам тиск.", "Ніж. Рана неглибока, але кров не зупиняється.", "Дякую. Дай мені ще трохи води."]'::jsonb, 0, null, 'Sada Vam mjerim tlak.', null, null, 'Прозвучало: «Sada Vam mjerim tlak.» — «Зараз виміряю вам тиск.».', (select id from public.lessons where id = '293af384-4ee2-5746-80a8-e8ffdc7009bc'), 'PUBLISHED', 'claude_assessment_v1'),
  ('b226ecc2-ad4b-5d46-8e34-8885c0d034e6', 'f5d5e3db-f84c-57b2-b162-74f0a73dc299', 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Так, будь ласка! Його треба видаляти?", "До чи після їжі?", "У вас великий синець. Можете ходити?"]'::jsonb, 2, null, 'Imate veliku modricu. Možete li hodati?', null, null, 'Прозвучало: «Imate veliku modricu. Možete li hodati?» — «У вас великий синець. Можете ходити?».', (select id from public.lessons where id = 'd5dee6c5-f510-57b9-a1ed-4b0a60e8e09a'), 'PUBLISHED', 'claude_assessment_v1'),
  ('feed7f84-6b91-5f1d-9389-53af19d2aab6', 'f5d5e3db-f84c-57b2-b162-74f0a73dc299', 3, 'A1', 'reading', 'understand', 'multiple_choice', 'Що потрібно, коли Софія повернеться?', 'Dijete je bolesno', '["Довідка від педіатра", "Оплата", "Новий одяг"]'::jsonb, 0, null, null, 'Olena: Dobro jutro, Sofija danas ne dolazi u vrtić. Ima temperaturu i kašlje.
Odgojiteljica: Dobro jutro! Žao mi je. Neka se odmara.
Olena: Hvala. Trebam li donijeti potvrdu od liječnika?
Odgojiteljica: Da, kad se vrati u vrtić, trebamo potvrdu od pedijatra.
Olena: U redu. Hvala i lijep dan!', 'Олена: Доброго ранку, Софія сьогодні не прийде в садок. У неї температура і кашель.
Вихователька: Доброго ранку! Мені шкода. Нехай відпочиває.
Олена: Дякую. Мені потрібно принести довідку від лікаря?
Вихователька: Так, коли вона повернеться в садок, нам потрібна довідка від педіатра.
Олена: Гаразд. Дякую і гарного дня!', 'Текст «Дитина хворіє». Правильна відповідь: «Довідка від педіатра».', null, 'PUBLISHED', 'claude_assessment_v1'),
  ('2e517ff1-1e64-596d-af7c-a5924daf976d', 'f5d5e3db-f84c-57b2-b162-74f0a73dc299', 4, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Dobro jutro. Jeste li natašte?', '["Jesam, ništa ne jedem od jučer.", "Trebamo madrac i komodu za spavaću sobu.", "Odlična! Glumac u glavnoj ulozi je fantastičan."]'::jsonb, 0, null, 'Dobro jutro. Jeste li natašte?', null, null, 'Діалог «У лабораторії»: «Dobro jutro. Jeste li natašte?» (Доброго ранку. Ви натщесерце?) — «Jesam, ništa ne jedem od jučer.» (Так, нічого не їм з учорашнього дня.).', (select id from public.lessons where id = '293af384-4ee2-5746-80a8-e8ffdc7009bc'), 'PUBLISHED', 'claude_assessment_v1'),
  ('e97113f4-3e5d-586a-8bdf-84118a6d3987', 'f5d5e3db-f84c-57b2-b162-74f0a73dc299', 5, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Kolika je temperatura na toplomjeru?', '["Na trgu u centru. Slavlje traje do jutra!", "Ja za Dinamo. Mislim da Dinamo danas pobjeđuje.", "Trideset osam. I stalno kiše, curi joj nos."]'::jsonb, 2, null, 'Kolika je temperatura na toplomjeru?', null, null, 'Діалог «Дитина хворіє»: «Kolika je temperatura na toplomjeru?» (Яка температура на термометрі?) — «Trideset osam. I stalno kiše, curi joj nos.» (Тридцять вісім. І постійно чхає, у неї тече з носа.).', (select id from public.lessons where id = '0df023bb-17fb-5006-91bf-3b911dd30295'), 'PUBLISHED', 'claude_assessment_v1'),
  ('8b69b224-bdcf-51c5-83d4-4f8ef032c276', 'f5d5e3db-f84c-57b2-b162-74f0a73dc299', 6, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Trebam li recept?', '["Слухаю вас?", "Ні, не потрібен.", "Є ці таблетки й сироп від кашлю."]'::jsonb, 1, null, null, 'Ljekarnica: Izvolite?
Andrij: Imate li nešto za prehladu?
Ljekarnica: Imamo ove tablete i sirup protiv kašlja.
Andrij: Trebam li recept?
Ljekarnica: Ne, ne trebate.', 'Ljekarnica: Слухаю вас?
Andrij: У вас є щось від застуди?
Ljekarnica: Є ці таблетки й сироп від кашлю.
Andrij: Мені потрібен рецепт?
Ljekarnica: Ні, не потрібен.', 'Діалог «Ліки від застуди»: «Trebam li recept?» — «Ne, ne trebate.», тобто «Ні, не потрібен.».', (select id from public.lessons where id = '123e68fa-291f-5ad6-8403-51db7020d641'), 'PUBLISHED', 'claude_assessment_v1'),
  ('1e1c361f-7cf6-59bf-bd4f-29c06951a5e7', 'f5d5e3db-f84c-57b2-b162-74f0a73dc299', 7, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Як часто ти ходиш у спортзал?». Що ви скажете?', null, '["Koliko često ideš u teretanu?", "Dijete kašlje noću.", "Pijte puno vode."]'::jsonb, 0, null, null, null, null, '«Як часто ти ходиш у спортзал?» — «Koliko često ideš u teretanu?».', (select id from public.lessons where id = '4bcf3852-7d28-5ceb-80ca-1870222d6834'), 'PUBLISHED', 'claude_assessment_v1'),
  ('b634fe45-1c73-586d-b898-af230965f2fd', 'f5d5e3db-f84c-57b2-b162-74f0a73dc299', 8, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «тіло»', null, '[]'::jsonb, null, 'tijelo', null, null, null, '«тіло» — tijelo.', (select id from public.lessons where id = '431b51ad-baa3-5387-94ac-a7273fdb9263'), 'PUBLISHED', 'claude_assessment_v1'),
  ('f987fae4-ba0b-5ae6-9abd-26b52de33da7', 'f5d5e3db-f84c-57b2-b162-74f0a73dc299', 9, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Мені потрібен терміновий запис.»', null, '["Trebam", "termin.", "hitan"]'::jsonb, null, 'Trebam hitan termin.', null, null, null, '«Мені потрібен терміновий запис.» — «Trebam hitan termin.».', (select id from public.lessons where id = '247c3445-6ba3-50f0-a441-9073d6734451'), 'PUBLISHED', 'claude_assessment_v1'),
  ('63025f3c-2150-54ff-ae92-b742c31557c7', 'f5d5e3db-f84c-57b2-b162-74f0a73dc299', 10, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Пийте багато води.»', null, '[]'::jsonb, null, 'Pijte puno vode.', null, null, null, '«Пийте багато води.» — «Pijte puno vode.».', (select id from public.lessons where id = '123e68fa-291f-5ad6-8403-51db7020d641'), 'PUBLISHED', 'claude_assessment_v1')
