insert into public.assessments (id, slug, kind, title_ua, cefr, module_id, order_index, pass_ratio, area_min_ratio, estimated_minutes, description_ua, status, source)
values ('f58e56ee-1aaf-5a7c-9347-7f7146f0c511', 'a1-m08', 'module', 'Перевірка модуля A1.8', 'A1', (select id from public.modules where level_code = 'A1' and order_index = 8), 8, 0.70, 0.50, 5, 'Після модуля: 10 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~5 хв.', 'PUBLISHED', 'claude_assessment_v1')
