insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options, correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('fbdeea34-0184-5eea-a7a7-5e060ef73f9c', 'f58e56ee-1aaf-5a7c-9347-7f7146f0c511', 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["У суботу концерт мого улюбленого гурту!", "І публіка в захваті.", "Завтра в нас річниця шлюбу. Десять років!"]'::jsonb, 2, null, 'Sutra nam je godišnjica braka. Deset godina!', null, null, 'Прозвучало: «Sutra nam je godišnjica braka. Deset godina!» — «Завтра в нас річниця шлюбу. Десять років!».', (select id from public.lessons where id = '0d0547ed-c0ef-53bd-bfe4-c482c84c40f4'), 'PUBLISHED', 'claude_assessment_v1'),
  ('e9e05bd5-bc2b-5cf3-bef2-9db1e02f7aae', 'f58e56ee-1aaf-5a7c-9347-7f7146f0c511', 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Мені потрібен свій м’яч?", "У тебе сьогодні ввечері побачення?", "Ти знаєш групу для українців у Загребі?"]'::jsonb, 1, null, 'Imaš li večeras spoj?', null, null, 'Прозвучало: «Imaš li večeras spoj?» — «У тебе сьогодні ввечері побачення?».', (select id from public.lessons where id = '0d0547ed-c0ef-53bd-bfe4-c482c84c40f4'), 'PUBLISHED', 'claude_assessment_v1'),
  ('508c39ea-ca35-5adf-90b9-21c0bca18a15', 'f58e56ee-1aaf-5a7c-9347-7f7146f0c511', 3, 'A1', 'reading', 'understand', 'multiple_choice', 'Коли вони йдуть у похід?', 'Planiramo izlet', '["У суботу", "У неділю", "У п’ятницю"]'::jsonb, 1, null, null, 'Marko: Idemo li u nedjelju na Sljeme?
Taras: Može! Kada krećemo?
Marko: Rano, u osam. Nalazimo se na stanici tramvaja.
Taras: Što trebam ponijeti?
Marko: Udobne cipele, vodu i sendvič. Gore je hladnije, uzmi i jaknu.
Taras: Super, vidimo se!', 'Марко: Підемо в неділю на Слєме?
Тарас: Можна! Коли вирушаємо?
Марко: Рано, о восьмій. Зустрічаємося на трамвайній зупинці.
Тарас: Що мені взяти?
Марко: Зручне взуття, воду й сендвіч. Нагорі холодніше, візьми й куртку.
Тарас: Чудово, до зустрічі!', 'Текст «Плануємо похід». Правильна відповідь: «У неділю».', null, 'PUBLISHED', 'claude_assessment_v1'),
  ('4208a3e8-8702-561d-a5ca-e41059bcfb45', 'f58e56ee-1aaf-5a7c-9347-7f7146f0c511', 4, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Što voliš raditi u slobodno vrijeme?', '["U četrnaest i dvadeset, s trećeg perona.", "U ladici, pored čarapa.", "Volim plivati i fotografirati."]'::jsonb, 2, null, 'Što voliš raditi u slobodno vrijeme?', null, null, 'Діалог «Що ти любиш робити?»: «Što voliš raditi u slobodno vrijeme?» (Що ти любиш робити у вільний час?) — «Volim plivati i fotografirati.» (Я люблю плавати й фотографувати.).', (select id from public.lessons where id = '1c16ceee-5f42-536a-98b4-7dcabaa3be6d'), 'PUBLISHED', 'claude_assessment_v1'),
  ('8b8ee3f1-2a03-5cb9-bafa-f330e5887b8c', 'f58e56ee-1aaf-5a7c-9347-7f7146f0c511', 5, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Hoću! Gdje se nalazimo?', '["Moram pogledati raspored. Imam puno obveza.", "Mene. Ja sam odgovoran za cijeli tim.", "Ispred kolodvora, u devet točno."]'::jsonb, 2, null, 'Hoću! Gdje se nalazimo?', null, null, 'Діалог «Плани на неділю»: «Hoću! Gdje se nalazimo?» (Хочу! Де зустрічаємося?) — «Ispred kolodvora, u devet točno.» (Перед вокзалом, рівно о дев’ятій.).', (select id from public.lessons where id = 'dde31f54-28b8-505b-aba6-3e578601fccb'), 'PUBLISHED', 'claude_assessment_v1'),
  ('c1ffef43-e271-5840-8bb5-f8dfeb3180d7', 'f58e56ee-1aaf-5a7c-9347-7f7146f0c511', 6, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Imaš li večeras spoj?', '["Дуже. І романтичний, веде мене на вечерю біля моря.", "Думаю, ти закохуєшся!", "Так! З Марком із спортзалу."]'::jsonb, 2, null, null, 'Ana: Imaš li večeras spoj?
Ivana: Imam! S Markom iz teretane.
Ana: Je li zgodan?
Ivana: Jako. I romantičan je, vodi me na večeru uz more.
Ana: Mislim da se zaljubljuješ!', 'Ana: У тебе сьогодні ввечері побачення?
Ivana: Так! З Марком із спортзалу.
Ana: Він гарний?
Ivana: Дуже. І романтичний, веде мене на вечерю біля моря.
Ana: Думаю, ти закохуєшся!', 'Діалог «Побачення»: «Imaš li večeras spoj?» — «Imam! S Markom iz teretane.», тобто «Так! З Марком із спортзалу.».', (select id from public.lessons where id = '0d0547ed-c0ef-53bd-bfe4-c482c84c40f4'), 'PUBLISHED', 'claude_assessment_v1'),
  ('1faf823f-6377-5261-ab74-9868403b209c', 'f58e56ee-1aaf-5a7c-9347-7f7146f0c511', 7, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Який гарний гол!». Що ви скажете?', null, '["S veseljem!", "Kakav lijep gol!", "Danas sam sretan."]'::jsonb, 1, null, null, null, null, '«Який гарний гол!» — «Kakav lijep gol!».', (select id from public.lessons where id = 'e61e3942-cd86-5f75-9eb5-d878242125bf'), 'PUBLISHED', 'claude_assessment_v1'),
  ('f4a0eb4a-db0c-5df5-925d-b05b5609592c', 'f58e56ee-1aaf-5a7c-9347-7f7146f0c511', 8, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «обійми»', null, '[]'::jsonb, null, 'zagrljaj', null, null, null, '«обійми» — zagrljaj.', (select id from public.lessons where id = '0d0547ed-c0ef-53bd-bfe4-c482c84c40f4'), 'PUBLISHED', 'claude_assessment_v1'),
  ('799ea848-cc36-50d5-8332-92e6bf8a4818', 'f58e56ee-1aaf-5a7c-9347-7f7146f0c511', 9, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Прочитай новину на сторінці.»', null, '["stranici.", "na", "Pročitaj", "vijest"]'::jsonb, null, 'Pročitaj vijest na stranici.', null, null, null, '«Прочитай новину на сторінці.» — «Pročitaj vijest na stranici.».', (select id from public.lessons where id = '4edd1556-f088-5d14-8f59-529b35747609'), 'PUBLISHED', 'claude_assessment_v1'),
  ('1cb25bd4-85a4-5082-88c2-638ad8321ff5', 'f58e56ee-1aaf-5a7c-9347-7f7146f0c511', 10, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Із задоволенням!»', null, '[]'::jsonb, null, 'S veseljem!', null, null, null, '«Із задоволенням!» — «S veseljem!».', (select id from public.lessons where id = '3ed8282d-b9fa-5151-b184-73fd352f8ba7'), 'PUBLISHED', 'claude_assessment_v1')
on conflict (id) do nothing;

