values ('084bad0e-e70f-52f4-8e2c-f5e75c422dcf', 'a1-m09', 'module', 'Перевірка модуля A1.9', 'A1', (select id from public.modules where level_code = 'A1' and order_index = 9), 9, 0.70, 0.50, 5, 'Після модуля: 10 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~5 хв.', 'PUBLISHED', 'claude_assessment_v1')
