insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options, correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('4207f503-aefd-5a96-adf3-7e6eb40ae2f3', '084bad0e-e70f-52f4-8e2c-f5e75c422dcf', 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Це для тебе і твоїх дітей.", "Весну. Тепліше, ніж узимку, і не надто спекотно.", "Кремшніту із Самобора і фрітуле на Різдво."]'::jsonb, 1, null, 'Proljeće. Toplije je nego zimi, a nije prevruće.', null, null, 'Прозвучало: «Proljeće. Toplije je nego zimi, a nije prevruće.» — «Весну. Тепліше, ніж узимку, і не надто спекотно.».', (select id from public.lessons where id = '0cb42e87-0ece-5e12-a07c-05cb5c370157'), 'PUBLISHED', 'claude_assessment_v1'),
  ('0056afdb-2d26-5aa0-b7ca-180ee27d92d2', '084bad0e-e70f-52f4-8e2c-f5e75c422dcf', 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Знову дощ? Сьогодні гарніше.", "Ні, це неробочий день. Тридцяте травня.", "Візьми завтра парасолю!"]'::jsonb, 2, null, 'Ponesi sutra kišobran!', null, null, 'Прозвучало: «Ponesi sutra kišobran!» — «Візьми завтра парасолю!».', (select id from public.lessons where id = '0cb42e87-0ece-5e12-a07c-05cb5c370157'), 'PUBLISHED', 'claude_assessment_v1'),
  ('fcb5d550-3480-5888-892d-6675eb885aa4', '084bad0e-e70f-52f4-8e2c-f5e75c422dcf', 3, 'A1', 'reading', 'understand', 'multiple_choice', 'Що зробити зі сміттям?', 'Pravila u nacionalnom parku', '["Забрати з собою", "Спалити", "Залишити біля стежки"]'::jsonb, 0, null, null, 'DOBRO DOŠLI U NACIONALNI PARK!
Hodajte samo po stazama.
Kupanje u jezerima je zabranjeno.
Ne hranite životinje i ne berite cvijeće.
Smeće nosite sa sobom.
Psi moraju biti na povodcu.
Hvala što čuvate prirodu!', 'ЛАСКАВО ПРОСИМО ДО НАЦІОНАЛЬНОГО ПАРКУ!
Ходіть лише стежками.
Купатися в озерах заборонено.
Не годуйте тварин і не зривайте квітів.
Сміття забирайте з собою.
Собаки мають бути на повідку.
Дякуємо, що бережете природу!', 'Текст «Правила в національному парку». Правильна відповідь: «Забрати з собою».', null, 'PUBLISHED', 'claude_assessment_v1'),
  ('0106774d-bb5c-53b4-bc2f-df5beee6936c', '084bad0e-e70f-52f4-8e2c-f5e75c422dcf', 4, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Sat vremena za jednu kavu?', '["Obuci plave hlače i bijelu majicu.", "Oko deset dana.", "Naravno! Sjedimo na terasi i pričamo."]'::jsonb, 2, null, 'Sat vremena za jednu kavu?', null, null, 'Діалог «Кава — це зустріч»: «Sat vremena za jednu kavu?» (Година на одну каву?) — «Naravno! Sjedimo na terasi i pričamo.» (Звісно! Сидимо на терасі й розмовляємо.).', (select id from public.lessons where id = '2fabcd03-324d-5355-b96e-022723fbeda7'), 'PUBLISHED', 'claude_assessment_v1'),
  ('4da699a3-81e5-595a-889c-710a94b679fb', '084bad0e-e70f-52f4-8e2c-f5e75c422dcf', 5, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Marko, ti si iz Dalmacije?', '["Nažalost, ne mogu. Moram raditi.", "Tri godine. Volim Rijeku, ali mi nedostaje dom.", "Da, iz Splita. To je na jugu, na moru."]'::jsonb, 2, null, 'Marko, ti si iz Dalmacije?', null, null, 'Діалог «Звідки ти?»: «Marko, ti si iz Dalmacije?» (Марку, ти з Далмації?) — «Da, iz Splita. To je na jugu, na moru.» (Так, зі Спліта. Це на півдні, біля моря.).', (select id from public.lessons where id = '8633c234-d638-57f1-ad92-1c78be43fb07'), 'PUBLISHED', 'claude_assessment_v1'),
  ('acd8adce-fd90-5f6f-81cf-da99c0fded1d', '084bad0e-e70f-52f4-8e2c-f5e75c422dcf', 6, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Gdje je najveći slap?', '["Цей маршрут триває чотири години. Ідемо пішки і кораблем через озеро.", "Наприкінці стежки. З оглядового майданчика вид чудовий.", "Ласкаво просимо до Національного парку Плітвіцькі озера!"]'::jsonb, 1, null, null, 'Vodič: Dobro došli u Nacionalni park Plitvička jezera!
Andrij: Koliko dugo traje obilazak?
Vodič: Ova staza traje četiri sata. Idemo pješice i brodom preko jezera.
Andrij: Gdje je najveći slap?
Vodič: Na kraju staze. S vidikovca je pogled prekrasan.', 'Vodič: Ласкаво просимо до Національного парку Плітвіцькі озера!
Andrij: Скільки триває екскурсія?
Vodič: Цей маршрут триває чотири години. Ідемо пішки і кораблем через озеро.
Andrij: Де найбільший водоспад?
Vodič: Наприкінці стежки. З оглядового майданчика вид чудовий.', 'Діалог «На Плітвіцьких озерах»: «Gdje je najveći slap?» — «Na kraju staze. S vidikovca je pogled prekrasan.», тобто «Наприкінці стежки. З оглядового майданчика вид чудовий.».', (select id from public.lessons where id = '84a20a00-701a-5ce5-a3c8-fca72986f912'), 'PUBLISHED', 'claude_assessment_v1'),
  ('7393a28b-bdfb-5f38-9286-d8071a82dc1e', '084bad0e-e70f-52f4-8e2c-f5e75c422dcf', 7, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Візьми парасолю!». Що ви скажете?', null, '["Sarma je zimsko jelo.", "Živim na sjeveru.", "Ponesi kišobran!"]'::jsonb, 2, null, null, null, null, '«Візьми парасолю!» — «Ponesi kišobran!».', (select id from public.lessons where id = '0cb42e87-0ece-5e12-a07c-05cb5c370157'), 'PUBLISHED', 'claude_assessment_v1'),
  ('db4e8ede-b2a4-5d8e-b285-72d3e58f9b0d', '084bad0e-e70f-52f4-8e2c-f5e75c422dcf', 8, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «тварина»', null, '[]'::jsonb, null, 'životinja', null, null, null, '«тварина» — životinja.', (select id from public.lessons where id = '84a20a00-701a-5ce5-a3c8-fca72986f912'), 'PUBLISHED', 'claude_assessment_v1'),
  ('8e65567f-889e-5a70-8216-e14eebd7132d', '084bad0e-e70f-52f4-8e2c-f5e75c422dcf', 9, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Ця стежка веде до озера.»', null, '["staza", "jezera.", "Ova", "do", "vodi"]'::jsonb, null, 'Ova staza vodi do jezera.', null, null, null, '«Ця стежка веде до озера.» — «Ova staza vodi do jezera.».', (select id from public.lessons where id = '84a20a00-701a-5ce5-a3c8-fca72986f912'), 'PUBLISHED', 'claude_assessment_v1'),
  ('0daeca56-8f45-509b-a649-55c44115eab3', '084bad0e-e70f-52f4-8e2c-f5e75c422dcf', 10, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «У печері холодно.»', null, '[]'::jsonb, null, 'U špilji je hladno.', null, null, null, '«У печері холодно.» — «U špilji je hladno.».', (select id from public.lessons where id = '84a20a00-701a-5ce5-a3c8-fca72986f912'), 'PUBLISHED', 'claude_assessment_v1')
