insert into public.assessments (id, slug, kind, title_ua, cefr, module_id, order_index, pass_ratio, area_min_ratio, estimated_minutes, description_ua, status, source)
values ('13b54933-137b-55d4-859b-f393d5af6da6', 'a1-m10', 'module', 'Перевірка модуля A1.10', 'A1', (select id from public.modules where level_code = 'A1' and order_index = 10), 10, 0.70, 0.50, 5, 'Після модуля: 10 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~5 хв.', 'PUBLISHED', 'claude_assessment_v1')
