insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options, correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('c780b765-f480-50f9-a482-aa6c3038abee', '13b54933-137b-55d4-859b-f393d5af6da6', 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Ні, дві хвилини пішки.", "Потрібне. Принесіть диплом і переклад.", "Горить у підвалі! Дзвоніть 112!"]'::jsonb, 0, null, 'Nije, dvije minute pješice.', null, null, 'Прозвучало: «Nije, dvije minute pješice.» — «Ні, дві хвилини пішки.».', (select id from public.lessons where id = '1c468857-b9aa-5143-aa84-6ea02aa2443c'), 'PUBLISHED', 'claude_assessment_v1'),
  ('27eaf2b7-2bc7-5be5-9078-0fdacd15fcb4', '13b54933-137b-55d4-859b-f393d5af6da6', 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Які документи потрібні?", "Чим ви займаєтеся?", "Скільки йому років?"]'::jsonb, 2, null, 'Koliko ima godina?', null, null, 'Прозвучало: «Koliko ima godina?» — «Скільки йому років?».', (select id from public.lessons where id = '42c31cfb-8680-5450-8453-245f3abd475a'), 'PUBLISHED', 'claude_assessment_v1'),
  ('a5c13313-e41f-5e4f-a16c-ab8d668b51a2', '13b54933-137b-55d4-859b-f393d5af6da6', 3, 'A1', 'reading', 'understand', 'multiple_choice', 'Де подавати заяву?', 'Obavijest MUP-a', '["У банку", "У поліцейському управлінні", "На пошті"]'::jsonb, 1, null, null, 'OBAVIJEST ZA STRANCE
Zahtjev za privremeni boravak predajete u policijskoj upravi prema mjestu stanovanja.
Trebate: važeću putovnicu, fotografiju, dokaz o smještaju i zdravstveno osiguranje.
Dokumente na stranom jeziku prevodi sudski tumač.
Na šalter dolazite s brojem iz automata. Radno vrijeme: 8 – 15 sati.', 'ОГОЛОШЕННЯ ДЛЯ ІНОЗЕМЦІВ
Заяву на тимчасове перебування подаєте в поліцейському управлінні за місцем проживання.
Потрібно: чинний паспорт, фотографія, підтвердження житла й медичне страхування.
Документи іноземною мовою перекладає присяжний перекладач.
До віконця підходите з номером з автомата. Години роботи: 8 – 15 година.', 'Текст «Документи в MUP». Правильна відповідь: «У поліцейському управлінні».', null, 'PUBLISHED', 'claude_assessment_v1'),
  ('faf1e306-0643-563b-922c-a233cdf4f76d', '13b54933-137b-55d4-859b-f393d5af6da6', 4, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Jesu li potrebne i ocjene s fakulteta?', '["Kajganu i tost, molim.", "Jesu, i popis predavanja.", "Na Badnjak kitimo bor, a navečer idemo na misu."]'::jsonb, 1, null, 'Jesu li potrebne i ocjene s fakulteta?', null, null, 'Діалог «Визнання диплома»: «Jesu li potrebne i ocjene s fakulteta?» (Потрібні також оцінки з університету?) — «Jesu, i popis predavanja.» (Так, і перелік предметів.).', (select id from public.lessons where id = '11b565a4-1e2a-50d2-8d9d-c05e84371402'), 'PUBLISHED', 'claude_assessment_v1'),
  ('94248149-4e07-59df-bc6e-b2e7eaa68f73', '13b54933-137b-55d4-859b-f393d5af6da6', 5, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Super! Što želite vidjeti?', '["Odlična! Glumac u glavnoj ulozi je fantastičan.", "Želim joj pokazati Plitvice i more.", "Na stoliću, pored zavjese."]'::jsonb, 1, null, 'Super! Što želite vidjeti?', null, null, 'Діалог «Плани на літо»: «Super! Što želite vidjeti?» (Чудово! Що ви хочете побачити?) — «Želim joj pokazati Plitvice i more.» (Хочу показати їй Плітвіце й море.).', (select id from public.lessons where id = '4b2bf351-c5fc-57ca-9fd9-24fb8a4bfc0d'), 'PUBLISHED', 'claude_assessment_v1'),
  ('87f0583a-efe6-5eb6-9711-37750d0e11a7', '13b54933-137b-55d4-859b-f393d5af6da6', 6, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Koja je najveća razlika između Ukrajine i Hrvatske?', '["Люди тут розслаблені, а в нас усі поспішають.", "Поступово звикаєш до всього.", "Схожа, але й дуже відмінна. Треба бути терплячим."]'::jsonb, 0, null, null, 'Ivan: Koja je najveća razlika između Ukrajine i Hrvatske?
Olena: Ljudi su ovdje opušteni, a kod nas svi žure.
Ivan: A jezik? Je li sličan ukrajinskom?
Olena: Sličan je, ali i jako različit. Treba biti strpljiv.
Ivan: Polako se navikneš na sve.', 'Ivan: Яка найбільша різниця між Україною і Хорватією?
Olena: Люди тут розслаблені, а в нас усі поспішають.
Ivan: А мова? Схожа на українську?
Olena: Схожа, але й дуже відмінна. Треба бути терплячим.
Ivan: Поступово звикаєш до всього.', 'Діалог «Різниця»: «Koja je najveća razlika između Ukrajine i Hrvatske?» — «Ljudi su ovdje opušteni, a kod nas svi žure.», тобто «Люди тут розслаблені, а в нас усі поспішають.».', (select id from public.lessons where id = 'dbb91fa1-4a97-5c04-99a8-8ac1d508b952'), 'PUBLISHED', 'claude_assessment_v1'),
  ('44758565-703f-5271-8ba4-591717599107', '13b54933-137b-55d4-859b-f393d5af6da6', 7, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я вчу хорватську, бо працюю тут». Що ви скажете?', null, '["Gdje je najbliže sklonište?", "Učim hrvatski jer radim ovdje.", "Mentalitet je ovdje drukčiji."]'::jsonb, 1, null, null, null, null, '«Я вчу хорватську, бо працюю тут.» — «Učim hrvatski jer radim ovdje.».', (select id from public.lessons where id = 'fc1baff0-0e48-5676-bd3c-47d88d31e582'), 'PUBLISHED', 'claude_assessment_v1'),
  ('1400703a-b2d5-5b26-b1b9-4e88fb6e046b', '13b54933-137b-55d4-859b-f393d5af6da6', 8, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «діти»', null, '[]'::jsonb, null, 'djeca', null, null, null, '«діти» — djeca.', (select id from public.lessons where id = 'fc1baff0-0e48-5676-bd3c-47d88d31e582'), 'PUBLISHED', 'claude_assessment_v1'),
  ('2d3b22ba-bde0-5512-a79f-f60d3bd49530', '13b54933-137b-55d4-859b-f393d5af6da6', 9, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Заняття починаються о восьмій.»', null, '["u", "osam.", "počinje", "Nastava"]'::jsonb, null, 'Nastava počinje u osam.', null, null, null, '«Заняття починаються о восьмій.» — «Nastava počinje u osam.».', (select id from public.lessons where id = '11b565a4-1e2a-50d2-8d9d-c05e84371402'), 'PUBLISHED', 'claude_assessment_v1'),
  ('77e98b6e-7515-56fb-bac2-4b80f625a92c', '13b54933-137b-55d4-859b-f393d5af6da6', 10, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Наш клас на другому поверсі.»', null, '[]'::jsonb, null, 'Naša učionica je na drugom katu.', null, null, null, '«Наш клас на другому поверсі.» — «Naša učionica je na drugom katu.».', (select id from public.lessons where id = '11b565a4-1e2a-50d2-8d9d-c05e84371402'), 'PUBLISHED', 'claude_assessment_v1')
on conflict (id) do nothing;

