insert into public.assessments (id, slug, kind, title_ua, cefr, module_id, order_index, pass_ratio, area_min_ratio, estimated_minutes, description_ua, status, source)
values ('aed2c0da-133a-52f5-91fd-3585d80f0666', 'a1-final', 'final', 'Фінальна перевірка рівня A1', 'A1', null, 100, 0.70, 0.50, 15, 'Кінець рівня (усі 10 модулів): 30 завдань на 4 навички. ~15 хв.', 'PUBLISHED', 'claude_assessment_v1')
