insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options, correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('182d70cf-6f81-5fa0-84b8-a2645d7dd77e', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Можу. Скільки коштує ремонт?", "Бажаєте місце біля вікна?", "Вибачте, мені можна тут паркуватися?"]'::jsonb, 0, null, 'Mogu. Koliko košta popravak?', null, null, 'Прозвучало: «Mogu. Koliko košta popravak?» — «Можу. Скільки коштує ремонт?».', (select id from public.lessons where id = 'cd5db261-a421-511d-8100-f86bf2335bbe'), 'PUBLISHED', 'claude_assessment_v1'),
  ('515dc66d-d037-5fa3-83b7-d3777bbd39f7', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Так, пилососю щодня!", "Подзвони в кабінет. Прийом можна перенести або скасувати.", "У ванній, біля мила. Швидко!"]'::jsonb, 2, null, 'U kupaonici, pored sapuna. Brzo!', null, null, 'Прозвучало: «U kupaonici, pored sapuna. Brzo!» — «У ванній, біля мила. Швидко!».', (select id from public.lessons where id = '54f17cf7-3c17-5978-b400-b6b6888c9f84'), 'PUBLISHED', 'claude_assessment_v1'),
  ('d4ac9eae-5954-5e23-8894-92e325c58bc1', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 3, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["А електрика? Розетка в порядку?", "Скільки коштує оренда?", "Де проблема?"]'::jsonb, 0, null, 'A struja? Je li utičnica u redu?', null, null, 'Прозвучало: «A struja? Je li utičnica u redu?» — «А електрика? Розетка в порядку?».', (select id from public.lessons where id = '8fc3399d-0405-5517-9358-d3ad6308d860'), 'PUBLISHED', 'claude_assessment_v1'),
  ('e7d94c21-a81b-5f30-ab1a-535e5126d052', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 4, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Без проблем, можу її замінити.", "Добре. Уже гаряче!", "Курка в паніровці або рагу зі стручкової квасолі."]'::jsonb, 0, null, 'Nema problema, mogu ga zamijeniti.', null, null, 'Прозвучало: «Nema problema, mogu ga zamijeniti.» — «Без проблем, можу її замінити.».', (select id from public.lessons where id = '6af82dd3-beb1-54cf-9c1b-44ec3cb12a35'), 'PUBLISHED', 'claude_assessment_v1'),
  ('71cf07e3-728d-5699-98c6-14e2c694fed3', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 5, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Звідки ви і як довго живете в Хорватії?", "Так. Шукаємо офіціанта на сезон. У вас є досвід?", "Кому мені дзвонити, якщо є проблема?"]'::jsonb, 2, null, 'Koga trebam zvati ako imam problem?', null, null, 'Прозвучало: «Koga trebam zvati ako imam problem?» — «Кому мені дзвонити, якщо є проблема?».', (select id from public.lessons where id = '2c56a486-dbbb-5102-b7cb-754c59cf94c3'), 'PUBLISHED', 'claude_assessment_v1'),
  ('082c833e-cb8d-5964-a7a3-079a0ac2dc90', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 6, 'A1', 'reading', 'understand', 'multiple_choice', 'Кому пише Олена?', 'Dijete je bolesno', '["Чоловікові", "Лікареві", "Виховательці"]'::jsonb, 2, null, null, 'Olena: Dobro jutro, Sofija danas ne dolazi u vrtić. Ima temperaturu i kašlje.
Odgojiteljica: Dobro jutro! Žao mi je. Neka se odmara.
Olena: Hvala. Trebam li donijeti potvrdu od liječnika?
Odgojiteljica: Da, kad se vrati u vrtić, trebamo potvrdu od pedijatra.
Olena: U redu. Hvala i lijep dan!', 'Олена: Доброго ранку, Софія сьогодні не прийде в садок. У неї температура і кашель.
Вихователька: Доброго ранку! Мені шкода. Нехай відпочиває.
Олена: Дякую. Мені потрібно принести довідку від лікаря?
Вихователька: Так, коли вона повернеться в садок, нам потрібна довідка від педіатра.
Олена: Гаразд. Дякую і гарного дня!', 'Текст «Дитина хворіє». Правильна відповідь: «Виховательці».', null, 'PUBLISHED', 'claude_assessment_v1'),
  ('540d01b9-c998-5c58-8fb0-2d992d0dc7f9', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 7, 'A1', 'reading', 'understand', 'multiple_choice', 'Коли прибуде посилка?', 'SMS od kurira', '["У понеділок", "Сьогодні між 14 і 17", "Завтра вранці"]'::jsonb, 1, null, null, 'Poštovani, Vaša pošiljka stiže danas između 14 i 17 sati. Kurir Vas zove prije dostave. Ako niste kod kuće, paket ostavljamo u paketomatu na adresi Ilica 25. Kod za otvaranje dobivate u novoj poruci. Za praćenje pošiljke posjetite našu stranicu.', 'Шановний(-а), ваша посилка прибуде сьогодні між 14 і 17 годиною. Кур’єр подзвонить вам перед доставкою. Якщо вас немає вдома, посилку залишимо в поштоматі за адресою Іліца, 25. Код для відкриття отримаєте в новому повідомленні. Щоб відстежити посилку, відвідайте наш сайт.', 'Текст «SMS від кур’єра». Правильна відповідь: «Сьогодні між 14 і 17».', null, 'PUBLISHED', 'claude_assessment_v1'),
  ('a843d936-ab05-5ebc-ba4a-0bc6acb333e6', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 8, 'A1', 'reading', 'understand', 'multiple_choice', 'Скільки яєць потрібно?', 'Recept: palačinke', '["Одне", "Три", "Два"]'::jsonb, 2, null, null, 'Trebate: dva jaja, pola litre mlijeka, dvjesto grama brašna, malo soli i ulja.
U zdjelu stavite jaja i mlijeko. Dodajte brašno i sol i dobro miješajte. Zagrijte tavu s malo ulja. Stavite malo smjese u tavu i pecite minutu sa svake strane. Palačinke jedite s pekmezom, medom ili čokoladom. Dobar tek!', 'Вам потрібно: два яйця, пів літра молока, двісті грамів борошна, трохи солі й олії.
У миску покладіть яйця й молоко. Додайте борошно й сіль і добре перемішайте. Розігрійте сковорідку з невеликою кількістю олії. Налийте трохи тіста на сковорідку й смажте хвилину з кожного боку. Млинці їжте з джемом, медом або шоколадом. Смачного!', 'Текст «Рецепт: млинці». Правильна відповідь: «Два».', null, 'PUBLISHED', 'claude_assessment_v1'),
  ('06a09489-9ac1-5719-95ac-9f970344c657', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 9, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Oprostite, gdje mogu kupiti kartu?', '["Radim kao vozač već pet godina.", "Sutra poslijepodne. Ostavite broj mobitela, molim.", "Na kiosku ili u tramvaju, kod vozača."]'::jsonb, 2, null, 'Oprostite, gdje mogu kupiti kartu?', null, null, 'Діалог «Де купити квиток?»: «Oprostite, gdje mogu kupiti kartu?» (Вибачте, де я можу купити квиток?) — «Na kiosku ili u tramvaju, kod vozača.» (У кіоску або в трамваї, у водія.).', (select id from public.lessons where id = '0ef458c5-53cf-530a-99cf-4ccd6e0132e5'), 'PUBLISHED', 'claude_assessment_v1'),
  ('015df820-ba3f-5526-9835-b40151965f12', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 10, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Zašto učite hrvatski?', '["Zato što želim razgovarati s kolegama.", "Poslije jela. I pijte puno vode.", "Pire ili kuhani krumpir. Uzmite pladanj."]'::jsonb, 0, null, 'Zašto učite hrvatski?', null, null, 'Діалог «На курсі»: «Zašto učite hrvatski?» (Чому ви вчите хорватську?) — «Zato što želim razgovarati s kolegama.» (Тому що хочу розмовляти з колегами.).', (select id from public.lessons where id = 'fc1baff0-0e48-5676-bd3c-47d88d31e582'), 'PUBLISHED', 'claude_assessment_v1'),
  ('45bbb0de-c83a-5192-b8b6-6cbbfeea882e', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 11, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Govedine ili svinjetine?', '["U prodaji. Radim s klijentima.", "Govedine. I dva odreska od puretine, molim.", "Ujutro šetam u parku, a popodne čitam."]'::jsonb, 1, null, 'Govedine ili svinjetine?', null, null, 'Діалог «У м’ясника»: «Govedine ili svinjetine?» (Яловичого чи свинячого?) — «Govedine. I dva odreska od puretine, molim.» (Яловичого. І дві відбивні з індички, будь ласка.).', (select id from public.lessons where id = 'ae33e31a-f937-5305-908e-3d957df15f6a'), 'PUBLISHED', 'claude_assessment_v1'),
  ('2122b27e-415d-5f36-bdb6-b4da0c429a41', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 12, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Kako si sada?', '["Do petnaestog u mjesecu.", "Oko tri sata autom. Na zapadu je.", "Puno bolje! Više nisam bolestan."]'::jsonb, 2, null, 'Kako si sada?', null, null, 'Діалог «Через тиждень»: «Kako si sada?» (Як ти зараз?) — «Puno bolje! Više nisam bolestan.» (Набагато краще! Я вже не хворий.).', (select id from public.lessons where id = '878c0712-e4e5-5a7d-aab5-510c781da0c7'), 'PUBLISHED', 'claude_assessment_v1'),
  ('8cd2e882-632f-526f-b395-c3007c151368', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 13, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Može. Kako ide selidba?', '["Vodu, sendvič i udobne cipele.", "Tablicu s cijenama. Ona je u privitku mog maila.", "Teško, ali prijevoz je jeftin jer prijatelj ima kombi."]'::jsonb, 2, null, 'Može. Kako ide selidba?', null, null, 'Діалог «Віддаємо ключі»: «Može. Kako ide selidba?» (Добре. Як іде переїзд?) — «Teško, ali prijevoz je jeftin jer prijatelj ima kombi.» (Важко, але перевезення дешеве, бо в друга є бус.).', (select id from public.lessons where id = '23f3aad6-4447-5b75-9dd1-891773457f7e'), 'PUBLISHED', 'claude_assessment_v1'),
  ('16c01603-1a36-5830-9018-7976a13512c6', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 14, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Mogu li ovdje provjeriti gume?', '["Odlična! Glumac u glavnoj ulozi je fantastičan.", "Možete, zrak je iza postaje.", "Sličan je, ali i jako različit. Treba biti strpljiv."]'::jsonb, 1, null, 'Mogu li ovdje provjeriti gume?', null, null, 'Діалог «На заправці»: «Mogu li ovdje provjeriti gume?» (Чи можу я тут перевірити шини?) — «Možete, zrak je iza postaje.» (Можете, повітря — за заправкою.).', (select id from public.lessons where id = 'd6ca64d8-4c71-5936-a930-51e400f5681d'), 'PUBLISHED', 'claude_assessment_v1'),
  ('bdbccb4e-2f05-5f0d-ba39-7c83028f9f97', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 15, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Imam putovnicu. Koliko košta ovjera?', '["Radim kao sobarica u hotelu. Moj muž je kuhar.", "Nekoliko eura. Ovjeru dobivate odmah.", "U ladici, pored čarapa."]'::jsonb, 1, null, 'Imam putovnicu. Koliko košta ovjera?', null, null, 'Діалог «У нотаріуса»: «Imam putovnicu. Koliko košta ovjera?» (Є паспорт. Скільки коштує засвідчення?) — «Nekoliko eura. Ovjeru dobivate odmah.» (Кілька євро. Засвідчення отримаєте одразу.).', (select id from public.lessons where id = 'fe2839bc-fd72-5e8b-bc0e-937d48a90aa8'), 'PUBLISHED', 'claude_assessment_v1'),
  ('5626b795-0366-534d-ab95-8d1dc685440c', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 16, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Koliko traje vožnja?', '["О чотирнадцятій двадцять, з третьої платформи.", "Близько чотирьох годин.", "Один квиток туди й назад, будь ласка."]'::jsonb, 1, null, null, 'Andrij: Kada polazi vlak za Rijeku?
Službenica: U četrnaest i dvadeset, s trećeg perona.
Andrij: Koliko traje vožnja?
Službenica: Oko četiri sata.
Andrij: Jednu povratnu kartu, molim.', 'Andrij: Коли відправляється поїзд до Рієки?
Službenica: О чотирнадцятій двадцять, з третьої платформи.
Andrij: Скільки триває поїздка?
Službenica: Близько чотирьох годин.
Andrij: Один квиток туди й назад, будь ласка.', 'Діалог «На вокзалі»: «Koliko traje vožnja?» — «Oko četiri sata.», тобто «Близько чотирьох годин.».', (select id from public.lessons where id = 'cae7a47d-7fb4-5b03-a8cc-5a0df2ccd92f'), 'PUBLISHED', 'claude_assessment_v1'),
  ('c6655850-bc51-5b8c-a2f6-54ffdb865383', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 17, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Je li namješten?', '["Так, але немає пральної машини.", "Добрий день, я телефоную щодо оголошення про квартиру.", "Так, квартира ще вільна."]'::jsonb, 0, null, null, 'Oksana: Dobar dan, zovem zbog oglasa za stan.
Stanodavac: Da, stan je još slobodan.
Oksana: Je li namješten?
Stanodavac: Jest, ali nema perilice.
Oksana: Koliko je najamnina?
Stanodavac: Petsto pedeset eura i režije.', 'Oksana: Добрий день, я телефоную щодо оголошення про квартиру.
Stanodavac: Так, квартира ще вільна.
Oksana: Вона мебльована?
Stanodavac: Так, але немає пральної машини.
Oksana: Скільки коштує оренда?
Stanodavac: П’ятсот п’ятдесят євро плюс комунальні.', 'Діалог «Дзвінок щодо оголошення»: «Je li namješten?» — «Jest, ali nema perilice.», тобто «Так, але немає пральної машини.».', (select id from public.lessons where id = '278947e3-ae50-5818-abd7-7f07b8ab5c44'), 'PUBLISHED', 'claude_assessment_v1'),
  ('fdc6ee7f-680c-57d2-9247-0231bffcb8b6', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 18, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Jesi li sretna ovdje?', '["Щодня розумію більше. Тепер можу розмовляти з тобою!", "А мова?", "Так. У мене є робота, квартира й друзі."]'::jsonb, 2, null, null, 'Ana: Jesi li sretna ovdje?
Iryna: Jesam. Imam posao, stan i prijatelje.
Ana: A jezik?
Iryna: Svaki dan razumijem više. Sada mogu razgovarati s tobom!', 'Ana: Ти щаслива тут?
Iryna: Так. У мене є робота, квартира й друзі.
Ana: А мова?
Iryna: Щодня розумію більше. Тепер можу розмовляти з тобою!', 'Діалог «Рік у Хорватії»: «Jesi li sretna ovdje?» — «Jesam. Imam posao, stan i prijatelje.», тобто «Так. У мене є робота, квартира й друзі.».', (select id from public.lessons where id = '4b2bf351-c5fc-57ca-9fd9-24fb8a4bfc0d'), 'PUBLISHED', 'claude_assessment_v1'),
  ('23dc952b-9024-5b43-9fc3-2d4cb6401be0', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 19, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'U redu. Na koje ime?', '["На п’ятницю на восьму.", "На ім’я Коваленко.", "Добрий день. Я хочу забронювати столик на двох."]'::jsonb, 1, null, null, 'Konobar: Restoran Lavanda, izvolite.
Andrij: Dobar dan. Želim rezervirati stol za dvoje.
Konobar: Za kada?
Andrij: Za petak u osam.
Konobar: U redu. Na koje ime?
Andrij: Na ime Kovalenko.', 'Konobar: Ресторан «Лаванда», слухаю.
Andrij: Добрий день. Я хочу забронювати столик на двох.
Konobar: На коли?
Andrij: На п’ятницю на восьму.
Konobar: Добре. На яке ім’я?
Andrij: На ім’я Коваленко.', 'Діалог «Бронювання»: «U redu. Na koje ime?» — «Na ime Kovalenko.», тобто «На ім’я Коваленко.».', (select id from public.lessons where id = '5e4a1c56-3931-58bb-81af-cb598966da77'), 'PUBLISHED', 'claude_assessment_v1'),
  ('c72d011c-c750-57fc-9dd5-caa62f612ba2', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 20, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Де туалетний папір?». Що ви скажете?', null, '["Ova haljina je jeftinija.", "Trebam vrećicu.", "Gdje je toaletni papir?"]'::jsonb, 2, null, null, null, null, '«Де туалетний папір?» — «Gdje je toaletni papir?».', (select id from public.lessons where id = '9ba8e62a-83fd-5b08-9e01-760bc0f7219f'), 'PUBLISHED', 'claude_assessment_v1'),
  ('4c4bd3e9-33f3-53b6-8d42-8ccc465f9de8', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 21, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я хочу відкрити рахунок». Що ви скажете?', null, '["Moj sin ide u vrtić.", "Želim otvoriti račun.", "Gdje je najbliže sklonište?"]'::jsonb, 1, null, null, null, null, '«Я хочу відкрити рахунок.» — «Želim otvoriti račun.».', (select id from public.lessons where id = '1c468857-b9aa-5143-aa84-6ea02aa2443c'), 'PUBLISHED', 'claude_assessment_v1'),
  ('16bfc03d-4d41-5416-8699-442c76115bba', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 22, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Їдь повільніше, швидкість велика». Що ви скажете?', null, '["Moram li ovdje platiti?", "Vozi sporije, brzina je velika.", "Koči polako, cesta je mokra."]'::jsonb, 1, null, null, null, null, '«Їдь повільніше, швидкість велика.» — «Vozi sporije, brzina je velika.».', (select id from public.lessons where id = '06f927cf-f38c-51b5-a1f9-696698ad23fb'), 'PUBLISHED', 'claude_assessment_v1'),
  ('8163d62a-973b-566e-a4a7-9a717e3c2d2e', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 23, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «терплячий»', null, '[]'::jsonb, null, 'strpljiv', null, null, null, '«терплячий» — strpljiv.', (select id from public.lessons where id = 'dbb91fa1-4a97-5c04-99a8-8ac1d508b952'), 'PUBLISHED', 'claude_assessment_v1'),
  ('594acc74-338c-50fa-a27e-17b4abe92463', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 24, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «сонце»', null, '[]'::jsonb, null, 'sunce', null, null, null, '«сонце» — sunce.', (select id from public.lessons where id = '71ab330d-abbe-57a7-870e-77e59daf3627'), 'PUBLISHED', 'claude_assessment_v1'),
  ('96a661d7-3813-5d2b-a860-083b88b3fb1f', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 25, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «двері»', null, '[]'::jsonb, null, 'vrata', null, null, null, '«двері» — vrata.', (select id from public.lessons where id = 'a42b9121-2ec0-5064-909b-f59f315b3c4a'), 'PUBLISHED', 'claude_assessment_v1'),
  ('69188fea-933e-50da-b126-84ff0f3cd0f1', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 26, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «На жаль, не можу.»', null, '["ne", "mogu.", "Nažalost,"]'::jsonb, null, 'Nažalost, ne mogu.', null, null, null, '«На жаль, не можу.» — «Nažalost, ne mogu.».', (select id from public.lessons where id = '3ed8282d-b9fa-5151-b184-73fd352f8ba7'), 'PUBLISHED', 'claude_assessment_v1'),
  ('20106eea-62f0-50d5-befc-c2217335bd7b', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 27, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Тут немає небезпеки.»', null, '["opasnosti.", "Ovdje", "nema"]'::jsonb, null, 'Ovdje nema opasnosti.', null, null, null, '«Тут немає небезпеки.» — «Ovdje nema opasnosti.».', (select id from public.lessons where id = '692e9310-7a5b-5adf-9f0a-a66b72fc5459'), 'PUBLISHED', 'claude_assessment_v1'),
  ('8929a278-e65d-5422-9819-1f285bdb5388', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 28, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Я працюю з клієнтами.»', null, '["klijentima.", "s", "Radim"]'::jsonb, null, 'Radim s klijentima.', null, null, null, '«Я працюю з клієнтами.» — «Radim s klijentima.».', (select id from public.lessons where id = 'd813e9c0-2331-59d8-90f1-cea7e9a61c7d'), 'PUBLISHED', 'claude_assessment_v1'),
  ('f9308daa-9dde-5d91-8566-69f7a7c0c90e', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 29, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Можна скуштувати?»', null, '[]'::jsonb, null, 'Mogu li probati?', null, null, null, '«Можна скуштувати?» — «Mogu li probati?».', (select id from public.lessons where id = '3e652232-866b-5edf-ac05-d61ee7a325fe'), 'PUBLISHED', 'claude_assessment_v1'),
  ('3312fb17-953c-5782-932b-a24972a42aca', 'aed2c0da-133a-52f5-91fd-3585d80f0666', 30, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Я хочу схуднути, але не люблю дієт.»', null, '[]'::jsonb, null, 'Želim mršaviti, ali ne volim dijete.', null, null, null, '«Я хочу схуднути, але не люблю дієт.» — «Želim mršaviti, ali ne volim dijete.».', (select id from public.lessons where id = '4bcf3852-7d28-5ceb-80ca-1870222d6834'), 'PUBLISHED', 'claude_assessment_v1')
on conflict (id) do nothing;

-- Журнал перевірки (один запис на тест)
insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
select 'assessment', a.id, null, a.status, 'auto_passed', 'script', '[]'::jsonb, 'Бета: тести рівня (§60) за рішенням власника 2026-10-15 (assessment_v1), як уроки A0/A1. Потрібна перевірка носієм.'
from public.assessments a
where a.source = 'claude_assessment_v1' and a.slug in ('a1-m01', 'a1-m02', 'a1-m03', 'a1-m04', 'a1-m05', 'a1-mid', 'a1-m06', 'a1-m07', 'a1-m08', 'a1-m09', 'a1-m10', 'a1-final')
  and not exists (select 1 from public.content_reviews c where c.entity_id = a.id and c.notes = 'Бета: тести рівня (§60) за рішенням власника 2026-10-15 (assessment_v1), як уроки A0/A1. Потрібна перевірка носієм.');

-- Самоперевірка: якщо щось не так — усе відкочується
do $$
declare v_tests int; v_items int; v_bad int;
begin
  select count(*) into v_tests from public.assessments where source = 'claude_assessment_v1' and slug in ('a1-m01', 'a1-m02', 'a1-m03', 'a1-m04', 'a1-m05', 'a1-mid', 'a1-m06', 'a1-m07', 'a1-m08', 'a1-m09', 'a1-m10', 'a1-final') and cefr = 'A1';
  select count(*) into v_items from public.assessment_items i join public.assessments a on a.id = i.assessment_id
   where a.source = 'claude_assessment_v1' and a.slug in ('a1-m01', 'a1-m02', 'a1-m03', 'a1-m04', 'a1-m05', 'a1-mid', 'a1-m06', 'a1-m07', 'a1-m08', 'a1-m09', 'a1-m10', 'a1-final');
  select count(*) into v_bad from public.assessments a
   where a.source = 'claude_assessment_v1' and a.slug in ('a1-m01', 'a1-m02', 'a1-m03', 'a1-m04', 'a1-m05', 'a1-mid', 'a1-m06', 'a1-m07', 'a1-m08', 'a1-m09', 'a1-m10', 'a1-final') and (a.kind = 'module' and a.module_id is null);
  if v_tests <> 12 then raise exception 'Тестів %, очікувалось 12', v_tests; end if;
  if v_items <> 150 then raise exception 'Завдань %, очікувалось 150', v_items; end if;
  if v_bad > 0 then raise exception '% тестів модуля без модуля', v_bad; end if;
  raise notice 'Готово: тести рівня A1 — %, завдань — %', v_tests, v_items;
end $$;
